const BIG=[{"id":"forms","name":"Form Finder","blurb":"Sort things by the form of energy they hold.","badge":"Form Finder","intro":["Energy comes in forms. I am the light form. Tap the form you see.","Two more forms now: electricity, and energy that is stored and waiting.","All six forms. Some of these are sneaky."],"levels":[[{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A rolling soccer ball","c":["Light","Heat","Motion"],"a":2,"why":"Anything that moves has motion energy. The faster it rolls, the more it has."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A glowing firefly","c":["Light","Heat","Motion"],"a":0,"why":"A firefly makes light with almost no heat. People call it cold light."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A cup of hot cocoa","c":["Light","Heat","Motion"],"a":1,"why":"Hot things hold heat energy. As the cocoa cools, that heat moves into the air and your hands."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A spinning merry-go-round","c":["Light","Heat","Motion"],"a":2,"why":"Spinning is motion too."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A rainbow","c":["Light","Heat","Motion"],"a":0,"why":"A rainbow is sunlight spread out into its colors by raindrops."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A warm heating pad","c":["Light","Heat","Motion"],"a":1,"why":"A heating pad turns electricity into heat."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A swing going back and forth","c":["Light","Heat","Motion"],"a":2,"why":"Back and forth is motion."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"The beam of a flashlight","c":["Light","Heat","Motion"],"a":0,"why":"The beam is light energy leaving the bulb."}],[{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A bolt of lightning","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":3,"why":"Lightning is a giant spark of electricity jumping through the air. It makes light and heat too, but it starts as electricity."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A stretched rubber band","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":4,"why":"The stretch stores energy. Let go and it turns into motion."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A peanut butter sandwich","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":4,"why":"Food stores energy your body can use later."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A sled sitting at the top of a hill","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":4,"why":"Being up high stores energy. The hill is holding it for you."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"The same sled zooming down the hill","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":2,"why":"On the way down, the stored energy turns into motion."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"The current in a phone charger cord","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":3,"why":"Electric current is energy moving along a wire."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A wind-up toy, wound tight","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":4,"why":"A wound spring stores energy until you let it go."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A hot stove burner","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":1,"why":"The burner is giving off heat."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"The glow of a campfire","c":["Light","Heat","Motion","Electricity","Stored energy"],"a":0,"why":"The glow you see is light. A fire gives off heat too."}],[{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"The energy locked in the centers of uranium atoms","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":5,"why":"Nuclear energy is held in the center of each atom, called the nucleus. It is stored too, but in a special place, so it gets its own name."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"Water held high behind a dam","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":4,"why":"Water held up high stores energy, just like the sled on the hill."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A full tank of gasoline","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":4,"why":"Fuel stores energy in its chemicals. Burning it lets the energy out as heat."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A charged battery","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":4,"why":"A battery stores energy in chemicals and gives it out as electricity."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"A drum skin shaking after a hit","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":2,"why":"Sound is a kind of motion: tiny, fast shaking that travels through the air."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"The zap from a doorknob after you cross a carpet","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":3,"why":"That zap is static electricity jumping from you to the metal."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"Moonlight","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":0,"why":"Moonlight is sunlight bouncing off the Moon."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"Atoms joining together deep in the Sun","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":5,"why":"Deep in the Sun, the centers of atoms join together. That nuclear energy becomes the Sun's heat and light."},{"t":"mc","fixed":1,"pre":"Which form of energy is this, mostly?","q":"Hot lava, melted rock from a volcano","c":["Light","Heat","Motion","Electricity","Stored energy","Nuclear"],"a":1,"why":"Lava carries heat from inside the Earth. It glows too, but most of its energy is heat."}]],"zone":"big"},{"id":"chains","name":"Chain Builder","blurb":"Put the links of an energy chain in order.","badge":"Chain Maker","intro":["Energy changes form link by link. Tap the links in order, first to last. Watch me change.","Longer chains now. Many of them start at the Sun.","The longest chains. Follow each one from its very start."],"levels":[[{"t":"order","q":"A flashlight","links":[["Battery","stash"],["Current in the wire","spark"],["Glowing bulb","glow"]],"why":"Stored energy became electricity, and electricity became light."},{"t":"order","q":"A wind-up car","links":[["Wound-up spring","stash"],["Gears turn","zip"],["Car rolls","zip"]],"why":"The spring's stored energy became motion."},{"t":"order","q":"A campfire","links":[["Dry log","stash"],["Flames","ember"],["Warm hands","ember"]],"why":"The wood's stored energy became heat, and some became light."},{"t":"order","q":"A toaster","links":[["Current from the outlet","spark"],["Wires glow red","ember"],["Warm toast","ember"]],"why":"Electricity became heat."}],[{"t":"order","q":"A solar garden light","links":[["Sunshine","glow"],["Solar panel makes current","spark"],["Battery fills up","stash"],["Lamp glows at night","glow"]],"why":"Light became electricity, was stored all day, and came back as light."},{"t":"order","q":"A bike ride","links":[["Sunshine","glow"],["Wheat plant grows","stash"],["Toast for breakfast","stash"],["Legs pedal","zip"]],"why":"Your ride started as sunlight that a plant caught."},{"t":"order","q":"A fan on a windy day","links":[["Wind turns the turbine","zip"],["Generator makes current","spark"],["Current runs to the house","spark"],["Fan blades spin","zip"]],"why":"Motion became electricity, and electricity became motion again somewhere else."},{"t":"order","q":"A water wheel","links":[["The Sun's heat lifts water into the sky","ember"],["Rain fills the high lake","stash"],["Water rushes down","zip"],["Wheel turns","zip"]],"why":"The Sun did the lifting. The water's height stored the energy until it fell."}],[{"t":"order","q":"Toast from a coal plant","links":[["Swamp plants catch sunlight","glow"],["Buried plants slowly become coal","stash"],["Burning coal boils water","ember"],["Steam spins a turbine","zip"],["Generator makes current","spark"],["Toaster wires glow","ember"]],"why":"This toast was made with sunlight from hundreds of millions of years ago."},{"t":"order","q":"A lamp from a nuclear plant","links":[["Uranium atoms split","core"],["Heat boils water","ember"],["Steam spins a turbine","zip"],["Generator makes current","spark"],["Lamp shines","glow"]],"why":"This chain never touches the Sun. It starts inside atoms."},{"t":"order","q":"Charging with wind","links":[["Sun warms land and sea unevenly","ember"],["Warm air rises and wind rushes in","zip"],["Turbine blades turn","zip"],["Generator makes current","spark"],["Battery charges","stash"]],"why":"Wind is air the Sun set moving."},{"t":"order","q":"A house warmed by the Earth","links":[["Hot rock deep underground","ember"],["Water pumped down turns to steam","ember"],["Steam spins a turbine","zip"],["Generator makes current","spark"],["Electric heater warms a room","ember"]],"why":"This chain starts with heat from inside the Earth, not with the Sun."}]],"zone":"big"},{"id":"sun","name":"Sunlight or Not?","blurb":"Trace each source back to where it started.","badge":"Sun Tracker","intro":["Most energy on Earth started as sunlight. A few things did not. Can you spot them?","More sources. Some started as sunlight a very long time ago.","Now say exactly where each one started. There are five answers."],"levels":[[{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A solar panel","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"It catches sunlight directly."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A banana","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"The banana plant caught sunlight and stored its energy in the fruit."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"Wind","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"The Sun warms the air, and warm and cool air trading places is wind."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A log for the fireplace","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"A tree is stored sunlight. Burning the log lets it back out."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A hot spring","c":["Started as sunlight","Did not start as sunlight"],"a":1,"why":"The water is warmed by heat from inside the Earth."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A river flowing downhill","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"The Sun lifted that water into the sky as vapor. Rain dropped it high up in the hills, and now it runs back down."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"Your own muscles","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"Your energy comes from food, and food starts with plants catching sunlight."}],[{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A lump of coal","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"Coal is plants that caught sunlight hundreds of millions of years ago."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"Gasoline","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"Oil formed from tiny sea life that lived on sunlight long ago."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A nuclear power plant","c":["Started as sunlight","Did not start as sunlight"],"a":1,"why":"Its energy comes from the centers of uranium atoms."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A hydropower dam","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"The Sun lifts the water. The dam catches it on the way back down."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A geyser","c":["Started as sunlight","Did not start as sunlight"],"a":1,"why":"Heat from inside the Earth boils the water."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A candle","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"Candle wax comes from oil or from bees, and both trace back to sunlight."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"Ocean tides","c":["Started as sunlight","Did not start as sunlight"],"a":1,"why":"Tides are raised by the pull of the Moon, with help from the pull of the Sun. Pull is not sunlight."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A hamburger","c":["Started as sunlight","Did not start as sunlight"],"a":0,"why":"Grass caught the sunlight, and the cow ate the grass."}],[{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A wind turbine","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":0,"why":"The Sun warmed the air this week, and the air moved."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A coal power plant","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":1,"why":"Coal is sunlight that plants caught hundreds of millions of years ago."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A geyser","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":2,"why":"Heat inside the Earth. Part of it is left from when the planet formed. Part comes from atoms slowly breaking down in the rock. Either way, it reaches us as heat inside the Earth."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A nuclear power plant","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":3,"why":"It splits the centers of uranium atoms. Uranium was made when stars exploded or crashed together, long before our Sun existed."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A tidal power station","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":4,"why":"The Moon's pull raises the tides, with help from the Sun's pull."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A hydropower dam","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":0,"why":"The Sun lifted that water not long ago."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"Natural gas for a stove","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":1,"why":"Gas formed from living things buried millions of years ago."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"A bowl of rice","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":0,"why":"The rice plant caught sunlight during the last growing season."},{"t":"mc","fixed":1,"pre":"Follow it back. Where did this energy start?","q":"The heat of a volcano","c":["Sunlight, lately","Sunlight, long ago","Heat inside the Earth","The centers of atoms","The pull of the Moon"],"a":2,"why":"Heat inside the Earth melts rock into magma."}]],"zone":"big"},{"id":"ledger","name":"Where Did It Go?","blurb":"Energy never disappears. Find where it went.","badge":"Bookkeeper","intro":["Here is the big rule: energy is never used up. It only changes form. So where did it go?","Now count it. What comes out has to add up to what went in. These numbers are pretend. The rule is real.","Bigger numbers, and two real ones from real machines."],"levels":[[{"t":"mc","q":"A ball bounces lower and lower, then stops. Where did its motion go?","c":["It turned into a little heat and sound","It disappeared","The floor kept it as motion"],"a":0,"why":"Each bounce warms the ball and floor a tiny bit and makes a sound. Nothing vanished."},{"t":"mc","q":"You rub your hands together fast. What does the motion turn into?","c":["Heat","Light","Stored energy"],"a":0,"why":"Rubbing turns motion into heat. That is why your hands feel warm."},{"t":"mc","q":"A flashlight is left on all night and the battery runs down. What happened to the battery's energy?","c":["It became light and heat","It was used up and is gone from the universe","It leaked back into the battery"],"a":0,"why":"The stored energy left the battery as light and heat. It still exists, spread out in the room."},{"t":"mc","q":"A swing slows down and stops when nobody pushes. Why?","c":["Rubbing on the air and the hooks turned its motion into heat","It got tired","Its energy was destroyed"],"a":0,"why":"Rubbing is called friction. It turns motion into a little heat."},{"t":"mc","q":"Can a machine give out more energy than goes into it?","c":["No, never","Yes, if it is a very good machine","Yes, if it spins fast enough"],"a":0,"why":"No machine has ever done it. What comes out always equals what went in."}],[{"t":"num","q":"A wind-up car lets go of its spring.","inn":"10 stored in the spring","parts":[["Motion",6],["Sound",1]],"miss":"Heat","a":3,"why":"6 + 1 + 3 = 10. Every bit is counted.","step":1},{"t":"num","q":"You hit a drum.","inn":"10 of motion from your arm","parts":[["Sound",4]],"miss":"Heat","a":6,"why":"4 + 6 = 10. In this pretend count, most of the hit ends up as heat.","step":1},{"t":"num","q":"You turn a hand-crank flashlight.","inn":"10 of motion from your hand","parts":[["Heat",7]],"miss":"Light","a":3,"why":"7 + 3 = 10.","step":1},{"t":"num","q":"A ball drops and bounces once.","inn":"10 of motion on the way down","parts":[["Motion on the way back up",6],["Sound",1]],"miss":"Heat","a":3,"why":"6 + 1 + 3 = 10. That is why the second bounce is lower.","step":1},{"t":"num","q":"A toy crane lifts a block.","inn":"10 of electricity","parts":[["Stored in the lifted block",5],["Sound",1]],"miss":"Heat","a":4,"why":"5 + 1 + 4 = 10. The lifted block now holds stored energy.","step":1}],[{"t":"num","q":"An old-style light bulb with a glowing wire. Real numbers, rounded.","inn":"100 of electricity","parts":[["Light",10]],"miss":"Heat","a":90,"why":"About 90 of every 100 becomes heat. That is why old bulbs are too hot to touch.","step":5},{"t":"num","q":"Electricity travels from a power plant to homes. Real United States average, rounded.","inn":"100 leaves the plant","parts":[["Heat lost in the wires",5]],"miss":"Arrives at homes","a":95,"why":"About 5 of every 100 warms the wires along the way.","step":5},{"t":"num","q":"A marble run. Pretend numbers.","inn":"100 stored at the top","parts":[["Motion at the bottom",55],["Sound",5]],"miss":"Heat","a":40,"why":"55 + 5 + 40 = 100.","step":5},{"t":"mc","q":"An inventor says: my machine takes in 100 and gives out 60 of motion, 25 of heat and 20 of sound. What is wrong?","c":["That adds up to 105, and a machine cannot give out more than it takes in","Nothing is wrong","Machines never make sound"],"a":0,"why":"60 + 25 + 20 = 105. Five extra can't come from nowhere."},{"t":"num","q":"A hand-crank radio. Pretend numbers.","inn":"100 of motion from your hand","parts":[["Sound",15],["Stored in its battery",35]],"miss":"Heat","a":50,"why":"15 + 35 + 50 = 100.","step":5}]],"zone":"big"},{"id":"paddle","name":"Paddle Wheel Lab","blurb":"Run James Joule's experiment: turn motion into heat.","badge":"Paddle Pro","custom":"paddle","intro":["A weight falls and turns paddles in a tub of water. Drop it and watch the thermometer.","Change the weight, the height and the number of drops. Warm the water by 0.2 degrees.","Predict first, then test. How does the warming change when you double something?"],"zone":"big"},{"id":"quiz","name":"Quick Quiz","blurb":"Five questions on the big idea.","badge":"Quiz Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What happens to energy when you use it?","c":["It changes into another form","It is gone forever","It turns into nothing"],"a":0,"why":"Energy only changes form."},{"t":"mc","q":"Which one is stored energy?","c":["A sandwich","A sunbeam","A gust of wind"],"a":0,"why":"Food stores energy until your body uses it."},{"t":"mc","q":"Where does a plant get the energy to grow?","c":["From sunlight","From the soil","From the wind"],"a":0,"why":"Soil gives a plant water and minerals. The energy comes from sunlight."},{"t":"mc","q":"A fan turns electricity mostly into what?","c":["Motion","Light","Stored energy"],"a":0,"why":"The blades and the air move."},{"t":"mc","q":"Sound is a kind of what?","c":["Motion","Light","Stored energy"],"a":0,"why":"Sound is tiny, fast shaking that travels through the air."}],[{"t":"mc","q":"What unit of energy is named after James Joule, who did the paddle wheel experiment?","c":["The joule","The watt","The volt"],"a":0,"why":"James Joule was a brewer's son from England. I am named after him too."},{"t":"mc","q":"Which of these did not start as sunlight?","c":["The heat in a hot spring","A lump of coal","A banana"],"a":0,"why":"Hot springs are warmed by heat from inside the Earth."},{"t":"mc","q":"A solar panel changes light into what?","c":["Electricity","Wind","Stored food"],"a":0,"why":"Light in, electricity out."},{"t":"mc","q":"Each time energy changes form, a little of it ends up as what?","c":["Heat","Nothing","Sunlight"],"a":0,"why":"Some heat shows up at nearly every link of a chain."},{"t":"mc","q":"Why do people call coal ancient sunlight?","c":["It formed from plants that caught sunlight long ago","It glows in the dark","It fell from the Sun"],"a":0,"why":"Those plants lived hundreds of millions of years ago."}],[{"t":"mc","q":"Energy is never made and never destroyed. What is that rule called?","c":["Conservation of energy","The law of gravity","The water cycle"],"a":0,"why":"Conservation means the total stays the same."},{"t":"mc","q":"About how much energy does it take to lift a very small apple one meter?","c":["1 joule","1,000 joules","1 million joules"],"a":0,"why":"A very small apple weighs about as much as a stick of butter. Lifting it one meter takes about one joule."},{"t":"mc","q":"A machine takes in 100 and its maker says it gives out 120. What do you say?","c":["That is impossible","It must be very well made","It needs more oil"],"a":0,"why":"Nothing gives out more energy than it takes in."},{"t":"mc","q":"Where does the heat inside the Earth come from?","c":["Heat left from when Earth formed, plus atoms breaking down in rock","Sunlight soaking down","Friction from the wind"],"a":0,"why":"Both sources matter. Sunlight warms only the top 10 meters or so of ground."},{"t":"mc","q":"An old-style light bulb turns most of its electricity into what?","c":["Heat","Light","Sound"],"a":0,"why":"About 90 of every 100 becomes heat."}]],"zone":"big"}];
const ELEC=[{"id":"bench","name":"Bulb Bench","blurb":"Build a circuit with batteries, bulbs and a switch.","badge":"Bench Builder","custom":"bench","intro":["This is my bench. A battery, a bulb, a switch and wire. Follow the job card.","One battery and up to two bulbs. You can put them in a row or side by side. Tap a bulb to unscrew it.","Now with numbers: volts, amps and watts. These bulbs are made for 0.9 watts."],"zone":"elec"},{"id":"light","name":"Will It Light?","blurb":"Look at a circuit and decide before it is switched on.","badge":"Loop Spotter","intro":["Current only flows when it has a complete loop: out of one end of the battery, through the bulb, and back in the other end.","Now something is bridging a gap in the wire. Does current get across?","Trickier ones. Check every part of the loop."],"levels":[[{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{},"c":["It lights","It stays dark"],"a":0,"why":"The loop is complete, so current flows all the way around."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"open"},"c":["It lights","It stays dark"],"a":1,"why":"There is a gap in the wire. Current cannot jump across it."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"sw":"open"},"c":["It lights","It stays dark"],"a":1,"why":"An open switch is a gap in the loop."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"sw":"closed"},"c":["It lights","It stays dark"],"a":0,"why":"A closed switch joins the loop again."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"oneEnd":1},"c":["It lights","It stays dark"],"a":1,"why":"Both wires are on the same end of the battery. Current needs to leave one end and come back to the other."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Paper clip"},"c":["It lights","It stays dark"],"a":0,"why":"A steel paper clip is metal, and metal lets current through."}],[{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Rubber band"},"c":["It lights","It stays dark"],"a":1,"why":"Rubber blocks electricity."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Aluminum foil"},"c":["It lights","It stays dark"],"a":0,"why":"Foil is metal. Current crosses it easily."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Plastic straw"},"c":["It lights","It stays dark"],"a":1,"why":"Plastic blocks electricity."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Coin"},"c":["It lights","It stays dark"],"a":0,"why":"Coins are metal."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"two":"same"},"c":["It lights","It stays dark"],"a":0,"why":"Two batteries facing the same way push together. The bulb is brighter than with one."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"two":"opp"},"c":["It lights","It stays dark"],"a":1,"why":"The two batteries push against each other. The pushes cancel and no current flows."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Dry string"},"c":["It lights","It stays dark"],"a":1,"why":"Dry string blocks electricity."}],[{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"two":"same","gap":"Short pencil lead"},"c":["It lights","It stays dark"],"a":0,"why":"Pencil lead is mostly graphite, one of the few solids that is not a metal but still conducts. The bulb glows dimly, because graphite resists the flow much more than wire does."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"short":1},"c":["It lights","It stays dark"],"a":1,"why":"The extra wire gives the current an easy path that skips the bulb. This is a short circuit. The wire and battery heat up fast, so never build one."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"sw":"closed","out":1},"c":["It lights","It stays dark"],"a":1,"why":"The switch is closed, but the bulb is unscrewed. An unscrewed bulb leaves a gap in the loop."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"House key"},"c":["It lights","It stays dark"],"a":0,"why":"A key is metal."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"two":"opp","sw":"closed"},"c":["It lights","It stays dark"],"a":1,"why":"The switch is closed, but the batteries face opposite ways and cancel."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"gap":"Glass marble"},"c":["It lights","It stays dark"],"a":1,"why":"Glass blocks electricity. Power lines hang from glass and ceramic holders for that reason."},{"t":"mc","fixed":1,"pre":"Look at the circuit. Will the bulb light?","q":"","pic":{"two":"same","gap":"Steel fork"},"c":["It lights","It stays dark"],"a":0,"why":"Complete loop, metal bridge, batteries pushing together."}]],"zone":"elec"},{"id":"conduct","name":"Through or Blocked?","blurb":"Sort conductors from insulators.","badge":"Conductor","intro":["Some things let electricity through. They are called conductors. Things that block it are called insulators.","More to sort. Think about what each thing is made of.","A few surprises here."],"levels":[[{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A copper wire","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Copper is one of the best conductors. Most wires are copper."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A rubber band","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Rubber is an insulator."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A steel paper clip","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Steel is a metal, and metals are conductors."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A plastic spoon","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Plastic is an insulator."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A piece of aluminum foil","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Aluminum is a metal."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A dry wooden craft stick","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Dry wood is an insulator."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A glass marble","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Glass is an insulator."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A nickel","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Coins are metal."}],[{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"The plastic coating on a lamp cord","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"That is its whole job. It keeps the current inside the wire and away from you."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A house key","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Keys are metal."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A dry cotton string","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Dry cotton is an insulator."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A gold ring","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Gold is a very good conductor. Tiny amounts are used inside phones and computers."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A rubber glove","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Rubber is an insulator."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A steel fork","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Steel is a metal."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A pencil eraser","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Erasers are rubber or plastic, and both are insulators."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"Water from the tap","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Tap water has minerals dissolved in it, and they carry some current. It is too little to light a bulb from a battery, but plenty to be dangerous with wall electricity."}],[{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"The lead of a pencil","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Pencil lead is mostly graphite. It is not a metal, but it conducts."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"Your own body","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Your body is mostly salty water, so current can pass through it. That is the reason for most electrical safety rules."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"Very pure water with nothing dissolved in it","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Pure water hardly conducts at all. The minerals and salts in ordinary water do the carrying."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"Salt water","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Dissolved salt makes water a much better conductor."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"Dry air","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Air is an insulator. It takes the enormous push of a thundercloud to force a spark through it, and that spark is lightning."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A silver spoon","c":["Lets electricity through","Blocks electricity"],"a":0,"why":"Silver is the best conductor of all the metals."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"The ceramic holder on a power pole","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Ceramic is an insulator. It keeps the current in the line and out of the pole."},{"t":"mc","fixed":1,"pre":"If this were part of a circuit, what would it do?","q":"A windowpane","c":["Lets electricity through","Blocks electricity"],"a":1,"why":"Glass is an insulator."}]],"zone":"elec"},{"id":"vaw","name":"Push, Flow, Power","blurb":"Volts, amps and watts, and what each one measures.","badge":"Watt Wise","intro":["Three ideas run every circuit: how hard the battery pushes, how much flows, and how fast energy gets used.","Each idea has a unit. Volts measure the push. Amps measure the flow. Watts measure how fast energy is used.","Here is the rule that ties them together: watts = volts × amps."],"levels":[[{"t":"mc","q":"In a circuit, what does the battery do?","c":["It pushes current around the loop","It makes the wire longer","It stores light"],"a":0,"why":"A battery is the pusher."},{"t":"mc","q":"What happens to a bulb when the push gets bigger?","c":["It gets brighter","It gets dimmer","Nothing changes"],"a":0,"why":"More push, more flow, more light."},{"t":"mc","q":"What moves through the wire when current flows?","c":["Tiny particles called electrons","Drops of water","Bits of light"],"a":0,"why":"Electrons are far too small to see. Metals have lots that are free to move."},{"t":"mc","q":"Which part of a flashlight turns electricity into light?","c":["The bulb","The switch","The battery"],"a":0,"why":"The bulb changes electricity into light and some heat."},{"t":"mc","q":"What does a switch do?","c":["It opens and closes a gap in the loop","It makes extra electricity","It stores electricity for later"],"a":0,"why":"Closed, the loop is whole. Open, there is a gap."}],[{"t":"mc","q":"What do volts measure?","c":["How hard the electricity is pushed","How much electricity flows","How fast energy is used"],"a":0,"why":"Volts are the push."},{"t":"mc","q":"What do amps measure?","c":["How much current flows","How hard it is pushed","How long the wire is"],"a":0,"why":"Amps are the flow."},{"t":"mc","q":"What do watts measure?","c":["How fast energy is being used","How hard the push is","How big the battery is"],"a":0,"why":"Watts are the power. One watt is one joule every second."},{"t":"mc","q":"An AA battery pushes with 1.5 volts. Two in a row, facing the same way, push with how much?","c":["3 volts","1.5 volts","0.75 volts"],"a":0,"why":"Pushes in a row add up: 1.5 + 1.5 = 3."},{"t":"mc","q":"About how hard does a wall outlet in the United States push?","c":["120 volts","12 volts","1.5 volts"],"a":0,"why":"That is 80 times the push of an AA battery. Outlets are never for experiments."},{"t":"mc","q":"Which one uses energy fastest?","c":["A 1,000-watt toaster","A 9-watt LED bulb","A 2-watt night light"],"a":0,"why":"More watts means energy is used faster."}],[{"t":"mc","q":"A phone charger gives 5 volts and 2 amps. How many watts is that?","c":["10 watts","7 watts","2.5 watts"],"a":0,"why":"5 × 2 = 10."},{"t":"mc","q":"A toaster on a 120-volt outlet draws 10 amps. How many watts?","c":["1,200 watts","130 watts","12 watts"],"a":0,"why":"120 × 10 = 1,200."},{"t":"mc","q":"A 60-watt lamp runs on 120 volts. How many amps flow?","c":["0.5 amps","2 amps","60 amps"],"a":0,"why":"120 × 0.5 = 60."},{"t":"mc","q":"One watt means one joule of energy every what?","c":["Second","Minute","Hour"],"a":0,"why":"A 9-watt bulb uses 9 joules every second."},{"t":"mc","q":"A 1,000-watt heater runs for one hour. How much energy did it use?","c":["1 kilowatt-hour","1 watt","1,000 volts"],"a":0,"why":"Kilo means a thousand. The kilowatt-hour is the unit an electric bill counts."},{"t":"mc","q":"A 9-watt LED bulb gives about as much light as an old 60-watt bulb. Where did the old bulb's extra energy go?","c":["Into heat","Into sound","Back into the wall"],"a":0,"why":"The old bulb turned most of its electricity into heat."}]],"zone":"elec"},{"id":"safe","name":"Safety Smart","blurb":"What is safe to experiment with, and what never is.","badge":"Safety Smart","intro":["AA and AAA batteries are safe to experiment with, with a grown-up nearby. Wall electricity is not. Here is how to tell the difference.","Now the reasons behind the rules.","How homes and power lines are built to keep people safe."],"levels":[[{"t":"mc","q":"Which of these is safe to experiment with?","c":["AA batteries, with a grown-up nearby","A wall outlet","A lamp cord"],"a":0,"why":"AA batteries push gently. Anything that plugs into the wall is not for experiments."},{"t":"mc","q":"You see a cord with its wires showing. What do you do?","c":["Leave it alone and tell a grown-up","Wrap it in tape yourself","Pull it out by the cord"],"a":0,"why":"Do not touch it, even if it is switched off. A grown-up can unplug it safely and replace it."},{"t":"mc","q":"What is the only thing that goes into a wall outlet?","c":["A plug","A paper clip","A finger"],"a":0,"why":"Only plugs, and only with dry hands."},{"t":"mc","q":"Your hands are wet. What do you do before touching a light switch or a plug?","c":["Dry them first","Nothing, wet is fine","Shake them once"],"a":0,"why":"Water helps current travel, so dry hands first."},{"t":"mc","q":"After a storm you see a power line lying on the ground. What do you do?","c":["Stay far away and tell a grown-up","Step over it carefully","Move it with a stick"],"a":0,"why":"Stay at least 35 feet away, about the length of a school bus. Always act as if the line is live, and do not touch anything it is touching, like a fence or a puddle. A grown-up calls 911."},{"t":"mc","q":"Your ball rolls inside a fenced area with electrical warning signs. What do you do?","c":["Leave it and tell a grown-up","Climb the fence","Reach through with a stick"],"a":0,"why":"The power company can get it back safely. The same goes for the green metal boxes in yards: stay off them."}],[{"t":"mc","q":"Why is a wall outlet dangerous when an AA battery is not?","c":["The outlet pushes about 80 times harder","Outlets are older","AA batteries have no electricity"],"a":0,"why":"120 volts against 1.5 volts."},{"t":"mc","q":"Why do plugged-in things stay away from the bathtub and sink?","c":["Water lets current through, and so does wet skin","Water is heavy","Soap ruins plugs"],"a":0,"why":"Ordinary water conducts, so current could reach you."},{"t":"mc","q":"How do you unplug something safely?","c":["Hold the plug itself and pull","Pull on the cord","Yank it fast"],"a":0,"why":"Pulling the cord can break the wires inside."},{"t":"mc","q":"Your kite is heading toward a power line. What do you do?","c":["Let go of the string and tell a grown-up","Pull it down hard","Climb up after it"],"a":0,"why":"Let it go. Never try to get a kite down from a line. A grown-up calls the power company. Fly kites in wide open places far from lines."},{"t":"mc","q":"Which tree is safe to climb?","c":["One far from any power line","One with a power line through its branches","One right next to a power pole"],"a":0,"why":"Branches can touch a line, and a line can be hidden by leaves. Pick trees well away from wires."},{"t":"mc","q":"Small, flat button batteries need extra care. Why?","c":["They are very dangerous if a small child swallows one","They are too weak to use","They are always dead"],"a":0,"why":"Keep them away from little brothers and sisters. If you think one was swallowed, or put in a nose or an ear, tell a grown-up right away, even if you are not sure. It is an emergency, and the grown-up gets medical help immediately."},{"t":"mc","q":"You hear thunder while playing outside. What do you do?","c":["Go indoors","Stand under a tall tree","Keep playing"],"a":0,"why":"Lightning is a giant spark. Indoors is the safe place. Stay in until the thunder has been gone for 30 minutes."}],[{"t":"mc","q":"A bird sits on a single power line and is fine. Why?","c":["It touches only one wire, so there is no loop through its body","Feathers stop all electricity","Birds are made of rubber"],"a":0,"why":"Current needs a complete loop. People on the ground would make one, so we never touch lines."},{"t":"mc","q":"A wire runs straight from one end of a battery to the other with nothing in between. What happens?","c":["The wire and battery heat up fast","A hidden bulb lights","Nothing at all"],"a":0,"why":"That is a short circuit. Too much current flows. Batteries can get hot enough to burn or leak, so never build one."},{"t":"mc","q":"What does a circuit breaker in a home do?","c":["It opens the circuit when too much current flows","It makes extra electricity","It stores power for the night"],"a":0,"why":"It makes a gap before the wires can overheat."},{"t":"mc","q":"Why do some plugs have a third, round prong?","c":["It gives leaking current a safe path into the ground","It makes the plug stronger","It holds the plug in tighter"],"a":0,"why":"It is called the ground prong."},{"t":"mc","q":"Someone is getting an electric shock. What do you do?","c":["Do not touch them, and shout for a grown-up to call 911","Pull them away","Pour water on them"],"a":0,"why":"Touching them could shock you too. A grown-up can shut off the power and call for help."},{"t":"mc","q":"Why do power lines hang from glass or ceramic holders?","c":["Those materials block current, so it stays in the line","They look nice","They are cheap"],"a":0,"why":"They are insulators."},{"t":"mc","q":"Outlets near sinks often have Test and Reset buttons. What is that outlet for?","c":["It shuts the power off in a split second if current leaks where it should not","It gives more power","It is a night light"],"a":0,"why":"It is called a GFCI outlet. It protects people near water."}]],"zone":"elec"},{"id":"equiz","name":"Quick Quiz","blurb":"Five questions on circuits.","badge":"Circuit Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What does a circuit need before the bulb will light?","c":["A complete loop","A very long wire","Two switches"],"a":0,"why":"Out of the battery, through the bulb, and back."},{"t":"mc","q":"Which one lets electricity through?","c":["A metal spoon","A plastic spoon","A wooden spoon"],"a":0,"why":"Metals are conductors."},{"t":"mc","q":"What happens when you open a switch?","c":["The loop gets a gap and the current stops","The current speeds up","The battery refills"],"a":0,"why":"The current stops everywhere in the loop at once."},{"t":"mc","q":"A battery turns its stored energy into what?","c":["Electricity","Wind","Sunlight"],"a":0,"why":"Stored energy in, electricity out."},{"t":"mc","q":"Why are metal wires covered in plastic?","c":["Plastic blocks electricity and keeps it in the wire","Plastic makes it flow faster","For decoration"],"a":0,"why":"Plastic is an insulator."}],[{"t":"mc","q":"Two bulbs are in a row on one loop. You unscrew one. What does the other do?","c":["It goes out","It gets brighter","It stays the same"],"a":0,"why":"One loop, one gap, everything stops."},{"t":"mc","q":"Why are the lights in a home wired side by side?","c":["Turning one off does not turn off the rest","It uses less wire","It makes the lights blink"],"a":0,"why":"Each light has its own loop."},{"t":"mc","q":"What do volts measure?","c":["The push","The flow","The power"],"a":0,"why":"Volts push, amps flow, watts are power."},{"t":"mc","q":"What do you call a material that lets current through easily?","c":["A conductor","An insulator","A generator"],"a":0,"why":"Copper, steel and aluminum are conductors."},{"t":"mc","q":"Two batteries face opposite ways in a loop. What happens?","c":["Their pushes cancel and the bulb stays dark","The bulb is twice as bright","The bulb blinks"],"a":0,"why":"Equal pushes in opposite directions add up to nothing."}],[{"t":"mc","q":"Which rule is right?","c":["Watts = volts × amps","Watts = volts + amps","Watts = volts ÷ amps"],"a":0,"why":"A 5-volt, 2-amp charger gives 10 watts."},{"t":"mc","q":"What does a kilowatt-hour measure?","c":["Energy","Push","Flow"],"a":0,"why":"It is the energy of 1,000 watts running for one hour."},{"t":"mc","q":"What is special about graphite, the lead in a pencil?","c":["It conducts even though it is not a metal","It is the best insulator","It glows in the dark"],"a":0,"why":"Very few solid non-metals conduct."},{"t":"mc","q":"You add more bulbs in a row to one battery. What happens to each bulb?","c":["Each gets dimmer, because they share the push","Each gets brighter","Nothing changes"],"a":0,"why":"Bulbs in a row split the battery's push between them."},{"t":"mc","q":"Two bulbs side by side draw 0.3 amps each. How much flows from the battery?","c":["0.6 amps","0.3 amps","0.15 amps"],"a":0,"why":"Side-by-side flows add up."}]],"zone":"elec"}];
const SUN=[{"id":"tilt","name":"Panel Tilt Lab","blurb":"Tilt a solar panel to catch the most sunlight.","badge":"Sun Catcher","custom":"tilt","intro":["A solar panel makes the most electricity when sunlight hits it straight on. Tilt the panel and watch the meter.","The noon Sun is high in summer and low in winter. Find the best tilt for each season.","Most panels are bolted in place for the whole year. Find one tilt that does well in every season."],"zone":"sun"},{"id":"sunout","name":"Light In, What Out?","blurb":"Sort the things sunlight can turn into.","badge":"Light Sorter","intro":["Sunlight can become electricity, heat, or food inside a plant. Which one happens here?","More to sort. Think about what each thing is for.","The three ways have names. Photovoltaic means light to electricity. Solar thermal means light to heat. Photosynthesis is how plants turn light into food."],"levels":[[{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A solar panel on a roof","c":["Electricity","Heat","Food made by a plant"],"a":0,"why":"Solar panels turn light straight into electricity."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A black car seat in July","c":["Electricity","Heat","Food made by a plant"],"a":1,"why":"Dark things soak up light and turn it into heat."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A leaf on a tree","c":["Electricity","Heat","Food made by a plant"],"a":2,"why":"Leaves use sunlight to make the tree's food."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A solar calculator","c":["Electricity","Heat","Food made by a plant"],"a":0,"why":"The little dark strip is a tiny solar panel."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A sidewalk at noon","c":["Electricity","Heat","Food made by a plant"],"a":1,"why":"The concrete soaks up light and warms."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A tomato plant","c":["Electricity","Heat","Food made by a plant"],"a":2,"why":"The plant stores the Sun's energy in its leaves, stems and fruit."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A solar garden light","c":["Electricity","Heat","Food made by a plant"],"a":0,"why":"A small panel makes electricity by day and a battery saves it for night."}],[{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A tank on a roof that warms bath water","c":["Electricity","Heat","Food made by a plant"],"a":1,"why":"It is a solar water heater. Sunlight warms the water directly."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A pizza-box solar oven","c":["Electricity","Heat","Food made by a plant"],"a":1,"why":"It traps sunlight as heat."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"The wide wings of a satellite","c":["Electricity","Heat","Food made by a plant"],"a":0,"why":"Those wings are solar panels. They power the satellite."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"Seaweed growing in the ocean","c":["Electricity","Heat","Food made by a plant"],"a":2,"why":"Seaweed and other algae make food from sunlight, just as land plants do."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A flashing road sign with a panel on top","c":["Electricity","Heat","Food made by a plant"],"a":0,"why":"The panel charges a battery that runs the lights."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A dark rock where a lizard warms up","c":["Electricity","Heat","Food made by a plant"],"a":1,"why":"The rock soaks up light and turns it into heat."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A field of corn","c":["Electricity","Heat","Food made by a plant"],"a":2,"why":"Every kernel is stored sunlight."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A solar phone charger","c":["Electricity","Heat","Food made by a plant"],"a":0,"why":"Light in, electricity out."}],[{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"Panels on a warehouse roof","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":0,"why":"Photo means light and volt is the unit of electric push."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A field of mirrors aiming sunlight at a boiler on a tower","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":1,"why":"The mirrors gather light onto the tower, where it becomes heat that boils water. The steam spins a turbine."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A rooftop tank that warms bath water","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":1,"why":"Solar thermal can be very simple."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"Algae in a pond","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":2,"why":"Algae make much of the oxygen you breathe while they do it."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A solar calculator","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":0,"why":"A tiny photovoltaic cell."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A pizza-box oven","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":1,"why":"Light to heat."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"The solar wings of the International Space Station","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":0,"why":"They power the whole station."},{"t":"mc","fixed":1,"pre":"Sunlight goes in. What comes out?","q":"A rainforest","c":["Photovoltaic: light to electricity","Solar thermal: light to heat","Photosynthesis: light to food"],"a":2,"why":"Photosynthesis on a huge scale."}]],"zone":"sun"},{"id":"sundark","name":"Soak or Bounce?","blurb":"Dark, light, shiny and clear things in the Sun.","badge":"Heat Trapper","intro":["Some things soak up sunlight and get warm. Some bounce it away. Some let it pass through.","A solar oven uses all three tricks at once. Here is how it is built.","The proper words: light that soaks in is absorbed, light that bounces is reflected, and light that passes through is transmitted."],"levels":[[{"t":"mc","q":"Which shirt feels hotter in the Sun?","c":["A black one","A white one","They feel the same"],"a":0,"why":"Dark colors soak up more light and turn it into heat."},{"t":"mc","q":"Which one bounces sunlight away best?","c":["Shiny foil","Black paper","Brown cardboard"],"a":0,"why":"Shiny surfaces bounce most of the light that hits them."},{"t":"mc","q":"On a sunny beach, where is the sand hotter?","c":["In the Sun","In the shade","The same in both"],"a":0,"why":"Sand in the Sun keeps soaking up light."},{"t":"mc","q":"What does sunlight do when it hits a clear window?","c":["Most of it passes through","It all bounces off","It all stops there"],"a":0,"why":"Clear things let light through."},{"t":"mc","q":"Why do many people wear light colors in summer?","c":["Light colors bounce more sunlight away","Light colors are thinner","Light colors make shade"],"a":0,"why":"Less light soaked up means less heat."}],[{"t":"mc","q":"Why is the floor of a solar oven black?","c":["Black soaks up light and turns it into heat","Black looks tidy","Black keeps bugs out"],"a":0,"why":"The black floor is where light becomes heat."},{"t":"mc","q":"Why does a solar oven have a foil flap?","c":["It bounces extra sunlight into the box","It keeps rain out","It makes shade"],"a":0,"why":"The flap works like a mirror."},{"t":"mc","q":"Why is the top of a solar oven covered in clear plastic?","c":["It lets light in and keeps the warm air from escaping","It keeps the light out","It makes the food shiny"],"a":0,"why":"Light gets in easily. Warm air does not get out easily."},{"t":"mc","q":"Why does a parked car get so hot on a sunny day?","c":["Sunlight comes in through the glass, turns to heat, and the heat is trapped","The engine keeps running","The tires make heat"],"a":0,"why":"A closed car is a solar oven nobody meant to build."},{"t":"mc","q":"Which roof stays cooler in summer?","c":["A white one","A black one","They stay the same"],"a":0,"why":"A white roof bounces more sunlight away."},{"t":"mc","q":"Why do skiers wear sunglasses on a bright day?","c":["Fresh snow bounces most of the sunlight back up","Snow makes its own light","Cold air hurts the eyes"],"a":0,"why":"Fresh snow reflects most of the light that lands on it."}],[{"t":"mc","q":"What is the word for light that a surface soaks up?","c":["Absorbed","Reflected","Transmitted"],"a":0,"why":"Absorbed light usually becomes heat."},{"t":"mc","q":"What is the word for light that bounces off a surface?","c":["Reflected","Absorbed","Transmitted"],"a":0,"why":"Mirrors and foil reflect most of their light."},{"t":"mc","q":"What is the word for light that passes through something?","c":["Transmitted","Absorbed","Reflected"],"a":0,"why":"Glass and clear plastic transmit most of their light."},{"t":"mc","q":"Why are solar panels dark blue or black?","c":["To absorb as much light as they can","To stay cool","To hide from birds"],"a":0,"why":"A panel can only use the light it absorbs."},{"t":"mc","q":"A solar panel turns about 20 of every 100 units of sunlight into electricity. What does most of the rest become?","c":["Heat","Sound","Stored energy"],"a":0,"why":"That is why panels feel warm in the Sun."},{"t":"mc","q":"Earth bounces about 30 of every 100 units of sunlight back into space. Which of these reflects the most?","c":["Clouds and ice","Oceans","Forests"],"a":0,"why":"Clouds, snow and ice are bright. Oceans and forests are dark and absorb most of their light."}]],"zone":"sun"},{"id":"sunwhen","name":"When the Sun Delivers","blurb":"Time of day, weather and seasons.","badge":"Sun Timer","intro":["A solar panel only works when light reaches it. When is that?","Days, seasons and the long trip from the Sun.","Big numbers, and why solar power needs a partner."],"levels":[[{"t":"mc","q":"When does a solar panel make the most electricity?","c":["Around the middle of a clear day","At sunrise","At midnight"],"a":0,"why":"In the middle of the day the Sun is highest and its light is strongest."},{"t":"mc","q":"How much does a solar panel make at night?","c":["Nothing","Half as much","The same as by day"],"a":0,"why":"No light, no electricity."},{"t":"mc","q":"What happens on a cloudy day?","c":["The panel makes less, but not nothing","The panel makes more","The panel makes nothing"],"a":0,"why":"Some light still comes through the clouds."},{"t":"mc","q":"In Ohio, which season gives a solar panel the most light?","c":["Summer","Winter","They are all the same"],"a":0,"why":"Summer days are longer and the Sun climbs higher."},{"t":"mc","q":"Snow covers a solar panel. What happens?","c":["It makes very little until the snow slides off","It makes more","Nothing changes"],"a":0,"why":"Snow blocks the light. Tilted panels shed it sooner."}],[{"t":"mc","q":"About how long does sunlight take to travel from the Sun to Earth?","c":["About 8 minutes","About 8 seconds","About 8 hours"],"a":0,"why":"The light you see left the Sun about 8 minutes ago."},{"t":"mc","q":"About how far away is the Sun?","c":["About 93 million miles","About 93 thousand miles","About 93 miles"],"a":0,"why":"That is why the trip takes light 8 minutes."},{"t":"mc","q":"In Cincinnati, about how long is the longest day of summer?","c":["About 15 hours","About 12 hours","About 20 hours"],"a":0,"why":"In late June the Sun is up for almost 15 hours."},{"t":"mc","q":"In Cincinnati, about how long is the shortest day of winter?","c":["About 9 and a half hours","About 12 hours","About 5 hours"],"a":0,"why":"In late December the Sun is up for just under 9 and a half hours."},{"t":"mc","q":"People use the most electricity in the early evening. What is the Sun doing then?","c":["Setting, so solar power is fading","Rising","At its highest"],"a":0,"why":"This mismatch is the main puzzle of solar power."},{"t":"mc","q":"What is a battery beside a solar farm for?","c":["Saving noon power for the evening","Making sunlight","Cleaning the panels"],"a":0,"why":"Stored at noon, used after sunset."}],[{"t":"mc","q":"Full sunlight delivers about how much power to each square meter of ground?","c":["About 1,000 watts","About 10 watts","About 1 million watts"],"a":0,"why":"That is about one toaster's worth for every square meter."},{"t":"mc","q":"The sunlight that reaches Earth in one hour holds about as much energy as all of humanity uses in how long?","c":["About a year","About a day","About a minute"],"a":0,"why":"There is plenty of sunlight. The hard parts are catching it and storing it."},{"t":"mc","q":"Where does the Sun's energy come from?","c":["Atoms joining together deep inside it","Burning coal","Electricity"],"a":0,"why":"It is nuclear energy, and it becomes heat and light."},{"t":"mc","q":"Why is sunlight stronger for a satellite than for a panel on the ground?","c":["There is no air or cloud in the way","The satellite is much closer to the Sun","Space is hot"],"a":0,"why":"Air and clouds soak up and scatter some of the light before it reaches the ground."},{"t":"mc","q":"Which kind of solar plant can keep making electricity for hours after sunset?","c":["A solar thermal plant that stores heat in tanks of melted salt","Ordinary panels with no battery","None of them"],"a":0,"why":"The stored heat keeps boiling water for the turbine."},{"t":"mc","q":"Solar farms make the most at noon. Towns need the most in the early evening. What do many new solar farms add?","c":["Big batteries","More mirrors","Taller fences"],"a":0,"why":"The batteries shift noon power into the evening."}]],"zone":"sun"},{"id":"sunfair","name":"Good At, Costs","blurb":"What sun power does well and what it costs.","badge":"Fair Judge: Sun","intro":["No energy source is perfect and none is the bad guy. Sort each fact about sun power.","More facts about sun power, good and costly.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It needs no fuel.","c":["Something it does well","Something it costs"],"a":0,"why":"Sunlight arrives for free."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes no smoke while it runs.","c":["Something it does well","Something it costs"],"a":0,"why":"Nothing is burned."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes nothing at night.","c":["Something it does well","Something it costs"],"a":1,"why":"So something else has to cover the night."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes less on cloudy days.","c":["Something it does well","Something it costs"],"a":1,"why":"Clouds block part of the light."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Panels fit on rooftops that were empty anyway.","c":["Something it does well","Something it costs"],"a":0,"why":"A roof can make power without using any new land."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Panels are silent.","c":["Something it does well","Something it costs"],"a":0,"why":"Panels have no moving parts."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The Sun will keep shining for billions of years.","c":["Something it does well","Something it costs"],"a":0,"why":"It will not run out in any future people need to plan for."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A big solar farm covers a lot of land.","c":["Something it does well","Something it costs"],"a":1,"why":"Land used for panels cannot easily be forest or most kinds of farm."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It can power places far from any power line.","c":["Something it does well","Something it costs"],"a":0,"why":"Cabins, road signs, boats and satellites all use it."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes the most at noon, but people need the most in the evening.","c":["Something it does well","Something it costs"],"a":1,"why":"The timing does not match, so storage is needed."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Panels have no moving parts and can last 25 years or more.","c":["Something it does well","Something it costs"],"a":0,"why":"Little wears out."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Making panels takes mining, factories and energy.","c":["Something it does well","Something it costs"],"a":1,"why":"Every energy source has to be built from something."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Its price has fallen a great deal since 2010.","c":["Something it does well","Something it costs"],"a":0,"why":"Solar panels cost a small fraction of what they did then."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"To cover the night it needs batteries or another source, and those cost extra.","c":["Something it does well","Something it costs"],"a":1,"why":"The panel is only part of the bill."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Old panels are hard to recycle, and few are recycled today.","c":["Something it does well","Something it costs"],"a":1,"why":"Engineers are working on better ways."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It adds no carbon dioxide to the air while it runs.","c":["Something it does well","Something it costs"],"a":0,"why":"Making the panel does add some, but running it adds none."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes less in winter, when days are short.","c":["Something it does well","Something it costs"],"a":1,"why":"In Ohio a panel makes far less in December than in June."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It can sit above parking lots and on warehouse roofs.","c":["Something it does well","Something it costs"],"a":0,"why":"Those spots make power and shade at the same time."}]],"zone":"sun"},{"id":"sunquiz","name":"Quick Quiz","blurb":"Five questions on sun power.","badge":"Solar Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What does a solar panel turn light into?","c":["Electricity","Wind","Water"],"a":0,"why":"Light in, electricity out."},{"t":"mc","q":"Which color soaks up the most sunlight?","c":["Black","White","Silver"],"a":0,"why":"Black absorbs nearly all the light that hits it."},{"t":"mc","q":"When does a solar panel make the most?","c":["Around the middle of the day","At sunset","At night"],"a":0,"why":"The Sun is highest in the middle of the day."},{"t":"mc","q":"What does a plant do with sunlight?","c":["It makes its food","It makes wind","It makes rain"],"a":0,"why":"That food is stored energy."},{"t":"mc","q":"What does shiny foil do to sunlight?","c":["It bounces it away","It soaks it up","It turns it off"],"a":0,"why":"Foil is a good reflector."}],[{"t":"mc","q":"Why are solar panels tilted?","c":["So sunlight hits them straight on","So rain can fill them","So birds cannot land"],"a":0,"why":"Straight-on light is the strongest."},{"t":"mc","q":"Compared with summer, the noon Sun in winter is what?","c":["Lower in the sky","Higher in the sky","In the same place"],"a":0,"why":"A lower Sun needs a steeper panel."},{"t":"mc","q":"About how long does sunlight take to reach Earth?","c":["8 minutes","8 seconds","8 days"],"a":0,"why":"About 8 minutes."},{"t":"mc","q":"What is the clear cover on a solar oven for?","c":["To let light in and keep warm air in","To keep light out","To cool the food"],"a":0,"why":"It works like the windows of a parked car."},{"t":"mc","q":"Why does solar power need a partner, such as a battery?","c":["It makes nothing at night and less under clouds","It is too loud","It makes too much smoke"],"a":0,"why":"The partner covers the gaps."}],[{"t":"mc","q":"A panel is bolted in place for the whole year. What is a good rule for its tilt?","c":["About the same number as your latitude","Always flat","Always straight up"],"a":0,"why":"Cincinnati is at about 39 degrees north, so about 39 degrees of tilt."},{"t":"mc","q":"Sunlight delivers 1,000 watts to a square meter. A panel turns 20 of every 100 into electricity. How many watts is that?","c":["200 watts","20 watts","1,000 watts"],"a":0,"why":"One fifth of 1,000 is 200."},{"t":"mc","q":"What is the word for turning light straight into electricity?","c":["Photovoltaic","Photosynthesis","Photograph"],"a":0,"why":"Photo means light."},{"t":"mc","q":"What powers the Sun?","c":["Atoms joining together","A giant fire of coal","Lightning"],"a":0,"why":"It is called fusion."},{"t":"mc","q":"In which month is Earth closest to the Sun?","c":["January","July","It is always the same distance"],"a":0,"why":"Seasons come from Earth's tilt, not from its distance. Earth is closest in early January."}]],"zone":"sun"}];
const WIND=[{"id":"turb","name":"Turbine Tuner","blurb":"Change the blades and the wind, and read the power.","badge":"Turbine Tuner","custom":"turb","intro":["This is a wind turbine. Wind pushes the blades, the blades spin a generator, and the generator makes electricity. Follow the job card.","Blade length matters more than you might guess. Test it.","Wind speed matters most of all. Test it."],"zone":"wind"},{"id":"windchain","name":"Where Wind Comes From","blurb":"Put the links in order, from the Sun to the breeze.","badge":"Wind Tracer","intro":["Wind is moving air, and the Sun is what sets it moving. Tap the links in order.","Breezes by the sea, and a turbine at work.","The longest chains: from the Sun all the way to a lamp."],"levels":[[{"t":"order","q":"How wind starts","links":[["Sunshine reaches the ground","glow"],["The ground warms the air above it","ember"],["Warm air rises and cooler air slides in","zip"]],"why":"That sliding air is wind."},{"t":"order","q":"A pinwheel","links":[["You blow","zip"],["Moving air pushes the blades","zip"],["The pinwheel spins","zip"]],"why":"Motion in the air became motion in the pinwheel."},{"t":"order","q":"An old windmill","links":[["Wind pushes the sails","zip"],["The shaft turns","zip"],["Millstones grind wheat into flour","zip"]],"why":"People have put wind to work for more than a thousand years."}],[{"t":"order","q":"A sea breeze on a sunny afternoon","links":[["The Sun warms the land faster than the sea","ember"],["Warm air over the land rises","zip"],["Cooler air from over the sea slides in","zip"],["You feel a breeze from the water","zip"]],"why":"Land heats up faster than water."},{"t":"order","q":"A wind turbine","links":[["Wind pushes the blades","zip"],["The shaft spins a generator","zip"],["The generator makes current","spark"],["Wires carry it to town","spark"]],"why":"Motion became electricity."},{"t":"order","q":"A breeze after dark","links":[["After sunset the land cools faster than the sea","ember"],["Air over the warmer sea rises","zip"],["Cool air from the land slides out to sea","zip"],["The breeze now blows toward the water","zip"]],"why":"At night the breeze turns around."}],[{"t":"order","q":"From the Sun to your lamp, by wind","links":[["Sunlight reaches the Earth","glow"],["The ground warms unevenly and heats the air","ember"],["Warm air rises and cool air rushes in","zip"],["Wind turns the blades","zip"],["A generator makes current","spark"],["Your lamp lights","glow"]],"why":"Light, heat, motion, electricity and light again."},{"t":"order","q":"The great winds of the Earth","links":[["The Sun heats the land and sea near the equator most","ember"],["Hot air there rises high","zip"],["It spreads away from the equator and cools","zip"],["Cool air sinks and flows back along the ground","zip"],["Earth's spin bends that flow into steady winds","zip"]],"why":"Sailors crossed oceans on these steady winds."},{"t":"order","q":"Saving wind for later","links":[["Wind turns the blades at night","zip"],["A generator makes current","spark"],["A battery charges","stash"],["The battery gives current back the next evening","spark"],["A stove heats dinner","ember"]],"why":"Stored energy lets wind power wait until it is needed."}]],"zone":"wind"},{"id":"windparts","name":"Inside the Turbine","blurb":"The parts of a wind turbine and what each does.","badge":"Turbine Expert","intro":["A wind turbine has a few big parts. What does each one do?","A closer look at the top of the tower.","How engineers think about turbines."],"levels":[[{"t":"mc","q":"Which part catches the wind?","c":["The blades","The tower","The base"],"a":0,"why":"The blades are shaped to be moved by the air flowing past them."},{"t":"mc","q":"Which part holds the blades up high?","c":["The tower","The generator","The wires"],"a":0,"why":"Wind is stronger high above the ground."},{"t":"mc","q":"How many blades do most big wind turbines have?","c":["Three","One","Ten"],"a":0,"why":"Three is the usual number."},{"t":"mc","q":"Which part makes the electricity?","c":["The generator","The tower","The blades"],"a":0,"why":"The blades spin it, and it turns motion into electricity."},{"t":"mc","q":"Which way does a wind turbine face?","c":["Into the wind","Away from the wind","Always north"],"a":0,"why":"It turns to face wherever the wind comes from."}],[{"t":"mc","q":"The box at the top of the tower holds the generator. What is it called?","c":["The nacelle","The cockpit","The attic"],"a":0,"why":"You say it nuh-SELL."},{"t":"mc","q":"A small wind vane sits on top of a turbine. What is it for?","c":["It tells the turbine which way the wind is blowing","It scares birds away","It is decoration"],"a":0,"why":"The turbine uses it to turn and face the wind."},{"t":"mc","q":"A turbine blade is shaped most like what?","c":["An airplane wing","A flat board","A spoon"],"a":0,"why":"The same curved shape that lifts a plane pulls a blade around."},{"t":"mc","q":"Why are turbine towers so tall?","c":["Wind is faster and steadier higher up","To be seen from far away","To keep the blades dry"],"a":0,"why":"Trees, hills and buildings slow the air near the ground."},{"t":"mc","q":"What does a turbine do in a dangerous storm?","c":["It turns its blades edge-on to the wind and stops","It spins as fast as it can","It lies down"],"a":0,"why":"Stopping protects the blades and the generator."},{"t":"mc","q":"About how long is one blade of a big modern turbine?","c":["About as long as a jumbo jet is wide, wingtip to wingtip","About as long as a car","About as long as a broom"],"a":0,"why":"Many are 200 feet long or more."}],[{"t":"mc","q":"The blades turn slowly. In many turbines, what does the gearbox do?","c":["It turns slow blade spins into fast spins for the generator","It stores wind","It cools the tower"],"a":0,"why":"The generator works best spinning fast. You met gears in Gizmo Lab."},{"t":"mc","q":"How does a generator make current?","c":["It spins magnets past coils of wire","It burns fuel","It squeezes air"],"a":0,"why":"Moving a magnet near a wire pushes current through the wire."},{"t":"mc","q":"No turbine can catch all the energy in the wind. About what is the most it could ever catch?","c":["About 59 of every 100","All 100 of every 100","About 5 of every 100"],"a":0,"why":"It is called the Betz limit."},{"t":"mc","q":"Why can a turbine never catch all of the wind's energy?","c":["The air has to keep moving to get out of the way behind the blades","The blades are too heavy","The law forbids it"],"a":0,"why":"If the air stopped completely, no new air could flow through."},{"t":"mc","q":"The blades look slow. About how fast do the tips of a big turbine move?","c":["Faster than a car on the highway","About walking speed","Faster than a jet plane"],"a":0,"why":"The tips travel a huge circle on every turn, often at well over 100 miles per hour."},{"t":"mc","q":"Why three blades and not two or twelve?","c":["Three run smoothly and catch plenty of wind without too much weight","Three is a lucky number","Twelve would be too colorful"],"a":0,"why":"More blades add weight and cost for little extra power."}]],"zone":"wind"},{"id":"windsite","name":"Windy or Calm?","blurb":"Pick the best places to put a turbine.","badge":"Site Scout","intro":["A turbine is only as good as its spot. Is this a good one?","Real places now.","How engineers choose a site."],"levels":[[{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"An open hilltop","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Nothing blocks the wind up there."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"A deep valley full of trees","c":["Good spot for a turbine","Poor spot for a turbine"],"a":1,"why":"The hills and trees block and slow the wind."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"Flat, open farmland","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Wind crosses open land without much to slow it."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"A street between tall buildings","c":["Good spot for a turbine","Poor spot for a turbine"],"a":1,"why":"Buildings block the wind and make it gusty."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"Out at sea, a few miles from shore","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Wind over open water is strong and steady."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"The middle of a forest","c":["Good spot for a turbine","Poor spot for a turbine"],"a":1,"why":"Trees slow the air near the ground."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"A wide, treeless plain","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Open plains are some of the windiest places."}],[{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"The Great Plains, from Texas to North Dakota","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"This is the windiest big region of the United States, and it has the most turbines."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"The open water of one of the Great Lakes","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Wind over the lakes is strong and steady. No turbines stand in the Great Lakes yet, though. Ice and cost make building there hard."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"A sheltered hollow behind a ridge","c":["Good spot for a turbine","Poor spot for a turbine"],"a":1,"why":"The ridge blocks the wind."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"A mountain pass where wind squeezes through","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Squeezed wind speeds up. Some of the first big wind farms were built in passes."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"A backyard ringed by houses and trees","c":["Good spot for a turbine","Poor spot for a turbine"],"a":1,"why":"Too much is in the way."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"The flat farm country of northwest Ohio","c":["Good spot for a turbine","Poor spot for a turbine"],"a":0,"why":"Ohio's biggest wind farms stand there."},{"t":"mc","fixed":1,"pre":"A wind turbine needs strong, steady wind.","q":"Right beside an airport runway, where planes fly low","c":["Good spot for a turbine","Poor spot for a turbine"],"a":1,"why":"The wind may be fine, but tall towers and low aircraft do not mix."}],[{"t":"mc","q":"Compared with wind near the ground, the wind 100 meters up is usually what?","c":["Faster","Slower","Just the same"],"a":0,"why":"The ground, trees and buildings drag on the air."},{"t":"mc","q":"Why are the turbines in a wind farm spaced far apart?","c":["Each one leaves slower, churned-up air behind it","To leave room for parking","So they do not look crowded"],"a":0,"why":"The next turbine needs clean wind."},{"t":"mc","q":"Wind at sea is strong and steady. What is the cost?","c":["Building and fixing turbines at sea costs more","The sea has no wind at night","Salt water stops the blades"],"a":0,"why":"Everything has to go out by ship."},{"t":"mc","q":"Before building a wind farm, for how long do engineers usually measure the wind?","c":["A year or more","An hour","They do not measure it"],"a":0,"why":"They need to see every season."},{"t":"mc","q":"A site has wind twice as fast as another. About how much more power can a turbine make there?","c":["About 8 times","About 2 times","About 4 times"],"a":0,"why":"Two times two times two."},{"t":"mc","q":"In many places wind is strongest at night and in winter, and sunshine is strongest at noon and in summer. What does that make them?","c":["Good partners","Rivals","The same thing"],"a":0,"why":"Each can cover some of the other's gaps."}]],"zone":"wind"},{"id":"windfair","name":"Good At, Costs","blurb":"What wind power does well and what it costs.","badge":"Fair Judge: Wind","intro":["No energy source is perfect and none is the bad guy. Sort each fact about wind power.","More facts about wind power, good and costly.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It needs no fuel.","c":["Something it does well","Something it costs"],"a":0,"why":"Wind arrives for free."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes no smoke while it runs.","c":["Something it does well","Something it costs"],"a":0,"why":"Nothing is burned."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It stops when the air is calm.","c":["Something it does well","Something it costs"],"a":1,"why":"No wind, no power."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It can run at night.","c":["Something it does well","Something it costs"],"a":0,"why":"Wind does not need daylight."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It needs a wide, open, windy place.","c":["Something it does well","Something it costs"],"a":1,"why":"Many places are not windy enough."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Some people do not like how turbines look or sound.","c":["Something it does well","Something it costs"],"a":1,"why":"They are large, and their blades make a steady swish."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Farmers can keep growing crops right up to the tower.","c":["Something it does well","Something it costs"],"a":0,"why":"A turbine uses only a small patch of the field."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The windiest places are often far from cities, so long power lines are needed.","c":["Something it does well","Something it costs"],"a":1,"why":"Power lines cost money and take years to build."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Nobody can make the wind blow at dinnertime.","c":["Something it does well","Something it costs"],"a":1,"why":"Wind comes when it comes."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"One big turbine can power around a thousand homes over a year.","c":["Something it does well","Something it costs"],"a":0,"why":"And a wind farm can have a hundred turbines."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Blades can strike birds and bats.","c":["Something it does well","Something it costs"],"a":1,"why":"Builders study sites first and can slow the blades when bats are flying."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It uses no water to make electricity.","c":["Something it does well","Something it costs"],"a":0,"why":"Many power plants need a great deal of water for cooling."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"In windy places it is one of the cheapest ways to make new electricity.","c":["Something it does well","Something it costs"],"a":0,"why":"Its cost has fallen a lot since 2010."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Old blades are hard to recycle.","c":["Something it does well","Something it costs"],"a":1,"why":"They are made of tough fiberglass. New designs are easier to recycle."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It adds no carbon dioxide to the air while it runs.","c":["Something it does well","Something it costs"],"a":0,"why":"Building the turbine does add some, but running it adds none."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Turbines kill some birds and bats.","c":["Something it does well","Something it costs"],"a":1,"why":"Studies find they kill far fewer birds than cats or windows do, and the harm to bats is a real concern that engineers are working on."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It must shut down in storms and stands still in calm.","c":["Something it does well","Something it costs"],"a":1,"why":"A partner source or storage has to fill in."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Farmers are paid rent for the land a tower stands on.","c":["Something it does well","Something it costs"],"a":0,"why":"The field earns money from crops and wind at once."}]],"zone":"wind"},{"id":"windquiz","name":"Quick Quiz","blurb":"Five questions on wind power.","badge":"Wind Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What is wind?","c":["Moving air","Falling water","A kind of light"],"a":0,"why":"Air on the move."},{"t":"mc","q":"What sets the air moving?","c":["The Sun warming it","The Moon pulling it","Trees waving"],"a":0,"why":"Warm air rises and cooler air slides in."},{"t":"mc","q":"What does a wind turbine turn the wind's motion into?","c":["Electricity","Sunlight","Water"],"a":0,"why":"Motion in, electricity out."},{"t":"mc","q":"How many blades do most big turbines have?","c":["Three","Six","One"],"a":0,"why":"Three."},{"t":"mc","q":"What does a turbine make when the air is calm?","c":["Nothing","Half power","Full power"],"a":0,"why":"It needs wind."}],[{"t":"mc","q":"You double the length of a turbine's blades. About how much more power can it make?","c":["4 times","2 times","The same"],"a":0,"why":"The blades sweep a circle with 4 times the area."},{"t":"mc","q":"What is the box at the top of a turbine tower called?","c":["The nacelle","The cabin","The crow's nest"],"a":0,"why":"The generator is inside it."},{"t":"mc","q":"Why are turbine towers tall?","c":["Wind is faster higher up","To touch the clouds","To look impressive"],"a":0,"why":"Faster wind means much more power."},{"t":"mc","q":"On a sunny afternoon at the beach, which way does the breeze usually blow?","c":["From the sea toward the land","From the land toward the sea","Straight down"],"a":0,"why":"Warm air rises over the land and sea air slides in."},{"t":"mc","q":"What does a turbine do in a dangerous storm?","c":["It stops","It speeds up","It falls over"],"a":0,"why":"It turns its blades edge-on and waits."}],[{"t":"mc","q":"The wind speed doubles. About how much more power is in the wind?","c":["8 times","2 times","4 times"],"a":0,"why":"Two times two times two."},{"t":"mc","q":"About how much of the wind's energy could a perfect turbine catch?","c":["About 59 of every 100","All of it","About 1 of every 100"],"a":0,"why":"The Betz limit."},{"t":"mc","q":"What is inside a generator that makes current?","c":["Magnets and coils of wire","Fan blades in water","Burning fuel"],"a":0,"why":"A magnet moving past a wire pushes current."},{"t":"mc","q":"Blades twice as long sweep a circle with how much area?","c":["4 times as much","2 times as much","The same"],"a":0,"why":"Area grows with length times length."},{"t":"mc","q":"Which source pairs well with wind, because it is strong when wind is often weak?","c":["Sunshine","Moonlight","Lightning"],"a":0,"why":"Noon and summer for the Sun, night and winter for the wind, in many places."}]],"zone":"wind"}];
const WATER=[{"id":"dam","name":"Dam Gate Lab","blurb":"Raise the water, open the gate and read the power.","badge":"Gate Keeper","custom":"dam","intro":["Water held up high has stored energy. Open the gate and it becomes motion. Follow the job card.","Two things set a dam's power: how high the water is, and how much flows each second. Test each one.","A reservoir is a store of energy, and it can run out. Plan a night."],"zone":"water"},{"id":"waterchain","name":"Water's Round Trip","blurb":"Put the links in order, from the Sun to the turbine.","badge":"River Tracer","intro":["The Sun lifts water into the sky. Gravity brings it back down. Tap the links in order.","How a dam makes electricity, and how a dam can work as a battery.","The whole trip, from sunshine on the sea to a lamp in town."],"levels":[[{"t":"order","q":"How a river fills","links":[["Sunlight warms the sea","glow"],["The sea's water warms and rises as vapor","ember"],["Clouds drop rain on the hills","zip"],["The rain runs downhill as a river","zip"]],"why":"The Sun did the lifting. That is why water power traces back to sunlight."},{"t":"order","q":"An old water mill","links":[["The river pushes the wheel","zip"],["The wheel turns a shaft","zip"],["Millstones grind grain into flour","zip"]],"why":"People have used water wheels for about two thousand years."},{"t":"order","q":"A water slide","links":[["You climb the stairs, lifting yourself higher","stash"],["You sit at the top, up high","stash"],["You zoom down","zip"]],"why":"Climbing stored the energy. The slide turned it into motion."}],[{"t":"order","q":"A hydropower dam","links":[["Water waits high behind the dam","stash"],["It rushes down a big pipe","zip"],["It spins a turbine","zip"],["The generator makes current","spark"]],"why":"Stored energy, then motion, then electricity."},{"t":"order","q":"A dam that works as a battery","links":[["At noon, spare solar power runs a pump","spark"],["The pump pushes water up to a high lake","stash"],["In the evening the water runs back down","zip"],["A generator makes current for the town","spark"]],"why":"It is called pumped storage. Most of the world's stored electricity is kept this way."},{"t":"order","q":"A flood gate in a storm","links":[["Heavy rain fills the reservoir","stash"],["Operators open the spillway","zip"],["Extra water passes safely around the turbines","zip"],["The river below rises slowly, not all at once","zip"]],"why":"A spillway lets extra water out before it can spill over the top of the dam."}],[{"t":"order","q":"From the Sun to your lamp, by water","links":[["Sunlight warms the sea","glow"],["The sea's water warms and rises as vapor","ember"],["Rain and snow land on high ground and wait there","stash"],["Water rushes down through the dam","zip"],["A generator makes current","spark"],["Your lamp lights","glow"]],"why":"Light, heat, stored energy, motion, electricity and light again."},{"t":"order","q":"Snow in the mountains","links":[["Winter snow piles up high in the mountains","stash"],["Spring warmth melts it","ember"],["Meltwater fills the reservoir","stash"],["The dam makes power all summer","spark"]],"why":"A snowpack is a store of energy that waits for months."},{"t":"order","q":"A river with no big dam","links":[["A river drops down a steep stretch","zip"],["A side channel takes part of the flow","zip"],["The water spins a turbine","zip"],["It rejoins the river just below","zip"]],"why":"This is called run-of-river. It floods little land, but it cannot store water for later."}]],"zone":"water"},{"id":"damparts","name":"Parts of a Dam","blurb":"What each part of a hydropower dam does.","badge":"Dam Expert","intro":["A hydropower dam has a few big parts. What does each one do?","A closer look, and a dam near home.","How engineers think about dams."],"levels":[[{"t":"mc","q":"What does the dam itself do?","c":["It holds the river back so the water piles up high","It makes the water","It cleans the water"],"a":0,"why":"The higher the water, the more energy it stores."},{"t":"mc","q":"What is the lake behind a dam called?","c":["A reservoir","A puddle","A canal"],"a":0,"why":"A reservoir stores water, and that means it stores energy."},{"t":"mc","q":"Which part does the falling water spin?","c":["The turbine","The dam","The gate"],"a":0,"why":"A turbine is a modern water wheel."},{"t":"mc","q":"Which part makes the electricity?","c":["The generator","The reservoir","The gate"],"a":0,"why":"The turbine spins it."},{"t":"mc","q":"What does the gate do?","c":["It controls how much water flows through","It keeps boats warm","It makes rain"],"a":0,"why":"Open it wider for more power. Close it to save water."}],[{"t":"mc","q":"What is the big pipe that carries water down to the turbine called?","c":["The penstock","The chimney","The straw"],"a":0,"why":"The water pushes harder and harder as it drops through the penstock."},{"t":"mc","q":"What is a spillway for?","c":["Letting extra water pass safely in a flood","Catching fish","Making waves"],"a":0,"why":"Without one, floodwater could pour over the top of the dam."},{"t":"mc","q":"What is a fish ladder?","c":["A set of small pools like steps that lets fish swim up past a dam","A ladder for people who fish","A net"],"a":0,"why":"Fish such as salmon need to swim upstream to lay their eggs."},{"t":"mc","q":"Why is a dam thicker at the bottom than at the top?","c":["Water pushes harder the deeper it is","To save concrete","So boats can park"],"a":0,"why":"You can feel this push in your ears at the bottom of a pool."},{"t":"mc","q":"There is a hydropower plant on the Ohio River about 30 miles upriver from Cincinnati. What is its dam called?","c":["Meldahl","Hoover","Niagara"],"a":0,"why":"The Meldahl plant opened in 2016 at a dam that was already there for boats."},{"t":"mc","q":"How fast can a hydropower plant go from off to full power?","c":["In a few minutes","In a few days","In a few months"],"a":0,"why":"Operators only need to open the gates. That makes water power good at covering sudden needs."}],[{"t":"mc","q":"Engineers call the height that water falls at a dam its what?","c":["Head","Foot","Tail"],"a":0,"why":"More head means more power from every bucket of water."},{"t":"mc","q":"Which is the largest power station of any kind in the world?","c":["Three Gorges Dam in China, which runs on water","A coal plant in Ohio","A solar farm in Arizona"],"a":0,"why":"Its turbines can make about 22,500 megawatts."},{"t":"mc","q":"Hoover Dam is on which river?","c":["The Colorado","The Ohio","The Mississippi"],"a":0,"why":"It was finished in 1936 and holds back Lake Mead."},{"t":"mc","q":"Among renewable sources, where does water power rank for making electricity worldwide?","c":["It is the largest single one","It is the smallest","It is in the middle"],"a":0,"why":"Wind and solar are growing fast. Added together they now make more than water does, but water is still the biggest single one."},{"t":"mc","q":"A turbine and generator at a dam can turn about how much of the falling water's energy into electricity?","c":["About 90 of every 100","About 20 of every 100","About 5 of every 100"],"a":0,"why":"Water turbines are among the most efficient machines people build."},{"t":"mc","q":"Why can a dam not be built just anywhere?","c":["It needs a river with enough water and a valley to hold it","It needs salt water","It needs wind"],"a":0,"why":"In the United States, most of the best sites for big dams are already in use."}]],"zone":"water"},{"id":"stored","name":"Up High, Stored","blurb":"Height stores energy. How much?","badge":"Height Keeper","intro":["Lifting something stores energy in it. Letting it fall gets the energy back.","Water towers and water batteries.","Count it in joules."],"levels":[[{"t":"mc","q":"Two books are the same. One is on the floor and one is on a high shelf. Which has more stored energy?","c":["The one on the high shelf","The one on the floor","They have the same"],"a":0,"why":"Someone lifted it there, and lifting stored the energy."},{"t":"mc","q":"Two buckets sit on the same shelf. One is full of water and one is half full. Which has more stored energy?","c":["The full one","The half-full one","They have the same"],"a":0,"why":"More weight up high means more stored energy."},{"t":"mc","q":"A sled waits at the top of a hill. What kind of energy does it have?","c":["Stored energy","Motion energy","Light energy"],"a":0,"why":"It turns into motion on the way down."},{"t":"mc","q":"Where does the stored energy of water behind a dam come from?","c":["The Sun lifted the water there as vapor and rain","The dam pushed it up","Fish carried it"],"a":0,"why":"The Sun does the lifting for free."},{"t":"mc","q":"You carry a backpack up the stairs. What did you store in it?","c":["Energy, by lifting it higher","Heat","Nothing"],"a":0,"why":"It came from your breakfast."}],[{"t":"mc","q":"Why do towns put their water tanks on tall towers?","c":["The height pushes water through the pipes to every tap","To keep birds out","To be closer to the rain"],"a":0,"why":"The stored energy of height becomes water pressure."},{"t":"mc","q":"A pumped storage plant has spare electricity at noon. What does it do with it?","c":["It pumps water up to a high lake","It turns it into wind","It throws it away"],"a":0,"why":"The water waits up high until the power is needed."},{"t":"mc","q":"What kind of storage holds most of the world's stored electricity?","c":["Water pumped uphill","Phone batteries","Giant springs"],"a":0,"why":"Pumped water has been used this way for about a hundred years."},{"t":"mc","q":"A pump uses 10 units of electricity to lift water. When the water runs back down, about how much electricity comes back?","c":["About 8 units","About 10 units","About 20 units"],"a":0,"why":"A little is lost as heat each way. Nothing gives back more than it took."},{"t":"mc","q":"Which stores more energy?","c":["A big lake high in the hills","A big lake at sea level","A small pond at sea level"],"a":0,"why":"It takes both a lot of water and a lot of height."}],[{"t":"mc","q":"Lifting 1 kilogram up 1 meter stores about how much energy?","c":["About 10 joules","About 1 joule","About 1,000 joules"],"a":0,"why":"You met this in the Paddle Wheel Lab."},{"t":"mc","q":"A cubic meter of water weighs 1,000 kilograms. Held 10 meters up, about how much energy does it store?","c":["About 100,000 joules","About 10,000 joules","About 1,000 joules"],"a":0,"why":"1,000 kilograms times 10 meters times about 10."},{"t":"mc","q":"You double the height of the water behind a dam. What happens to the energy stored in each cubic meter?","c":["It doubles","It stays the same","It is four times as much"],"a":0,"why":"Stored energy grows in step with height."},{"t":"mc","q":"100,000 joules sounds like a lot. A 1,000-watt toaster uses that much in how long?","c":["100 seconds","1 second","A whole day"],"a":0,"why":"1,000 joules every second. That is why dams need so much water."},{"t":"mc","q":"Why does a dam's power drop when the reservoir is low?","c":["The water falls a shorter distance","The water gets colder","The turbine gets lonely"],"a":0,"why":"Less head means less energy from each cubic meter."}]],"zone":"water"},{"id":"waterfair","name":"Good At, Costs","blurb":"What water power does well and what it costs.","badge":"Fair Judge: Water","intro":["No energy source is perfect and none is the bad guy. Sort each fact about water power.","More facts about water power, good and costly.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes no smoke.","c":["Something it does well","Something it costs"],"a":0,"why":"Nothing is burned."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It can run day and night.","c":["Something it does well","Something it costs"],"a":0,"why":"Water flows in the dark too."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It needs the right kind of river.","c":["Something it does well","Something it costs"],"a":1,"why":"Many places have no river big or steep enough."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A dam blocks fish from swimming upstream.","c":["Something it does well","Something it costs"],"a":1,"why":"Fish ladders help some fish, but not all."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The lake behind a dam stores energy for later.","c":["Something it does well","Something it costs"],"a":0,"why":"Operators can save water until it is needed."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The lake covers land that used to be dry.","c":["Something it does well","Something it costs"],"a":1,"why":"Whatever was in the valley ends up under water."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It can be turned up or down in minutes.","c":["Something it does well","Something it costs"],"a":0,"why":"That makes it a good partner for sun and wind."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"In a drought it makes less.","c":["Something it does well","Something it costs"],"a":1,"why":"No rain, less water, less power."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A dam can last a hundred years.","c":["Something it does well","Something it costs"],"a":0,"why":"Hoover Dam has been running since the 1930s."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Farms, forests and sometimes whole towns in the valley are flooded when a dam is built.","c":["Something it does well","Something it costs"],"a":1,"why":"People who live there have to move."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The reservoir can also supply drinking water and hold back floods.","c":["Something it does well","Something it costs"],"a":0,"why":"One dam can do several jobs."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A dam changes the river below it.","c":["Something it does well","Something it costs"],"a":1,"why":"The water often runs colder and clearer, and carries less sand and mud to the banks downstream."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It adds almost no carbon dioxide to the air while it runs.","c":["Something it does well","Something it costs"],"a":0,"why":"Building the dam takes a great deal of concrete, which does add some."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Most of the best sites in the United States are already used.","c":["Something it does well","Something it costs"],"a":1,"why":"There is little room to build more big dams here."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Pumped storage lets it save spare power from sun and wind.","c":["Something it does well","Something it costs"],"a":0,"why":"It still holds more stored energy than all the world's big batteries put together, though batteries are catching up fast."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Plants rotting under a new reservoir can give off methane, a gas that warms the climate.","c":["Something it does well","Something it costs"],"a":1,"why":"This matters most in warm, shallow reservoirs."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It is one of the cheapest sources once the dam is built.","c":["Something it does well","Something it costs"],"a":0,"why":"The water is free and the dam lasts a long time."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Building a big dam costs a great deal and takes many years.","c":["Something it does well","Something it costs"],"a":1,"why":"Most of the cost comes before the first power is made."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Mud and sand slowly fill the reservoir.","c":["Something it does well","Something it costs"],"a":1,"why":"The river keeps carrying them in, and over many years the lake holds less water."}]],"zone":"water"},{"id":"waterquiz","name":"Quick Quiz","blurb":"Five questions on water power.","badge":"Water Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What lifts water up to the hills and mountains?","c":["The Sun, as vapor that falls as rain","Pumps","Fish"],"a":0,"why":"That is why water power traces back to sunlight."},{"t":"mc","q":"What is the lake behind a dam called?","c":["A reservoir","A river","A harbor"],"a":0,"why":"A reservoir."},{"t":"mc","q":"Water held up high has what kind of energy?","c":["Stored energy","Light energy","Sound energy"],"a":0,"why":"It becomes motion when it falls."},{"t":"mc","q":"What does the falling water spin?","c":["A turbine","A dam","A cloud"],"a":0,"why":"And the turbine spins the generator."},{"t":"mc","q":"What happens to a dam's power when the gate is closed?","c":["It stops, and the water waits","It doubles","It turns to steam"],"a":0,"why":"The energy stays stored."}],[{"t":"mc","q":"You double the height of the water and keep the same gate. What happens to the power?","c":["It doubles","It is 8 times as much","Nothing"],"a":0,"why":"Power grows in step with height."},{"t":"mc","q":"What is the big pipe down to the turbine called?","c":["The penstock","The spillway","The ladder"],"a":0,"why":"The penstock."},{"t":"mc","q":"What is pumped storage?","c":["Using spare power to pump water uphill, then letting it run down later","A way to make rain","A kind of fish ladder"],"a":0,"why":"A water battery."},{"t":"mc","q":"What is a spillway for?","c":["Letting floodwater pass safely","Catching fish","Storing electricity"],"a":0,"why":"It protects the dam."},{"t":"mc","q":"What happens to water power in a drought?","c":["It drops","It rises","Nothing changes"],"a":0,"why":"Less water means less power."}],[{"t":"mc","q":"A dam's power depends on which two things multiplied together?","c":["Height and flow","Height and color","Flow and temperature"],"a":0,"why":"Twice the height or twice the flow gives twice the power."},{"t":"mc","q":"What is the largest power station in the world?","c":["Three Gorges Dam","Hoover Dam","Meldahl Dam"],"a":0,"why":"It is on the Yangtze River in China."},{"t":"mc","q":"What do engineers call the height the water falls?","c":["Head","Lift","Step"],"a":0,"why":"More head, more power."},{"t":"mc","q":"About how much of the water's energy can a hydropower turbine and generator turn into electricity?","c":["About 90 of every 100","About 40 of every 100","About 10 of every 100"],"a":0,"why":"Far more than a solar panel or a wind turbine can catch. Sun and wind are free, though, so catching less still pays."},{"t":"mc","q":"A plant on a river with no big reservoir is called what?","c":["Run-of-river","Pumped storage","A water tower"],"a":0,"why":"It floods little land but cannot save water for later."}]],"zone":"water"}];
const GEO=[{"id":"well","name":"Drill Down Lab","blurb":"Drill into the Earth and take its temperature.","badge":"Deep Driller","custom":"well","intro":["The deeper you go into the Earth, the hotter it gets. Drill down and watch the thermometer.","A power plant works well with rock at about 150 degrees Celsius or hotter. Where can you find it?","Now with numbers. How fast does the rock warm as you go down?"],"zone":"geo"},{"id":"layers","name":"Down to the Core","blurb":"Put the Earth's layers and a power plant's steps in order.","badge":"Core Explorer","intro":["The Earth has layers, like a peach with a skin, flesh and a pit. Tap them in order.","How a power plant borrows heat from deep rock.","Geysers, and how a house can use the ground."],"levels":[[{"t":"order","q":"The Earth's layers, from the outside in","links":[["Crust: the thin rocky skin we live on","ember"],["Mantle: hot rock that flows very slowly","ember"],["Outer core: melted metal","ember"],["Inner core: a solid metal ball","ember"]],"why":"It gets hotter with every layer."},{"t":"order","q":"A hot spring","links":[["Rain soaks deep into the ground","zip"],["Hot rock warms the water","ember"],["Warm water rises back to the surface","zip"]],"why":"The water borrowed heat from the rock."},{"t":"order","q":"A volcano","links":[["Rock melts deep underground","ember"],["Melted rock rises through cracks","zip"],["It comes out as lava","ember"]],"why":"You can see more at Volcano Rim in Science Lab."}],[{"t":"order","q":"An Earth-heat power plant","links":[["Hot rock deep down heats water","ember"],["Steam rises up a well","zip"],["The steam spins a turbine","zip"],["A generator makes current","spark"],["The cooled water is pumped back down","zip"]],"why":"Sending the water back down lets the plant use it again and again."},{"t":"order","q":"Heating a town in Iceland","links":[["Hot water is pumped up from underground","ember"],["Pipes carry it to town","zip"],["It runs through heaters in each home","ember"],["The cooled water flows away or is sent back down","zip"]],"why":"Nothing is burned and no electricity is needed to make the heat."},{"t":"order","q":"From the Earth to your lamp","links":[["Heat inside the Earth","ember"],["Steam","ember"],["A spinning turbine","zip"],["Current in a wire","spark"],["Light from your lamp","glow"]],"why":"This chain never touches the Sun."}],[{"t":"order","q":"A geyser erupts","links":[["Water collects in a deep, narrow crack","stash"],["Hot rock heats the water at the bottom past boiling","ember"],["Some water flashes to steam","ember"],["The steam blasts the water above it into the air","zip"],["The crack refills and the wait starts again","stash"]],"why":"Old Faithful in Yellowstone does this about every hour and a half."},{"t":"order","q":"A heat pump warming a house in winter","links":[["The ground a few meters down stays mild all winter","ember"],["Liquid in buried pipes picks up that mild warmth","ember"],["A heat pump squeezes the warmth to make it hotter","spark"],["Warm air flows into the rooms","ember"]],"why":"The pump runs on electricity, but most of the heat comes from the ground."},{"t":"order","q":"A heat pump cooling a house in summer","links":[["The house is too warm","ember"],["The heat pump pulls heat out of the rooms","spark"],["Liquid in the pipes carries the heat underground","zip"],["The cooler ground soaks it up","ember"]],"why":"The same machine runs backward in summer."}]],"zone":"geo"},{"id":"geofacts","name":"Earth Heat Facts","blurb":"How hot, how deep and where.","badge":"Hot Rock Scholar","intro":["What is it like deep inside the Earth?","Where the heat comes from, and who uses it.","Records and numbers."],"levels":[[{"t":"mc","q":"As you go deeper into the Earth, what happens to the temperature?","c":["It gets hotter","It gets colder","It stays the same"],"a":0,"why":"Deep mines are hot enough that cool air has to be pumped in."},{"t":"mc","q":"What is melted rock called while it is still underground?","c":["Magma","Lava","Gravel"],"a":0,"why":"Once it reaches the surface it is called lava."},{"t":"mc","q":"Which of these is warmed by heat from inside the Earth?","c":["A hot spring","A puddle in the Sun","A campfire"],"a":0,"why":"Hot springs are warm even in winter."},{"t":"mc","q":"What is a geyser?","c":["A hot spring that shoots water and steam into the air","A kind of volcano made of ice","A deep lake"],"a":0,"why":"Geysers are rare. About half of all the world's geysers are in Yellowstone."},{"t":"mc","q":"Does the heat inside the Earth come from the Sun?","c":["No, it comes from inside the Earth itself","Yes, sunlight soaks all the way down","Yes, through volcanoes"],"a":0,"why":"Sunlight warms only the top 10 meters or so of ground."}],[{"t":"mc","q":"Where does the Earth's inner heat come from?","c":["Heat left from when the Earth formed, plus atoms slowly breaking down in the rock","Burning coal deep underground","Lightning"],"a":0,"why":"Both sources matter."},{"t":"mc","q":"About how hot is the very center of the Earth?","c":["About as hot as the surface of the Sun","About as hot as an oven","About as hot as boiling water"],"a":0,"why":"Roughly 5,000 to 6,000 degrees Celsius."},{"t":"mc","q":"In Iceland, about how many homes are heated with hot water from underground?","c":["About 9 of every 10","About 1 of every 10","None"],"a":0,"why":"Iceland sits on a crack in the Earth's crust where hot rock is close to the surface."},{"t":"mc","q":"Which country makes the most electricity from Earth heat?","c":["The United States","Canada","Australia"],"a":0,"why":"Most of it comes from California and Nevada."},{"t":"mc","q":"Hot springs, geysers and volcanoes are found mostly where?","c":["Near the edges of the Earth's great plates","In the middle of flat plains","Only at the North Pole"],"a":0,"why":"At plate edges, hot rock comes close to the surface."},{"t":"mc","q":"The ground a few meters down in your yard stays at about what temperature all year?","c":["About the same mild temperature, winter and summer","Freezing in winter and hot in summer","Boiling"],"a":0,"why":"In Cincinnati it is about 55 degrees Fahrenheit."}],[{"t":"mc","q":"In most places, about how much hotter does rock get with each kilometer of depth?","c":["About 25 degrees Celsius","About 1 degree Celsius","About 500 degrees Celsius"],"a":0,"why":"Near volcanoes it can climb several times faster."},{"t":"mc","q":"What is the largest group of Earth-heat power plants in the world?","c":["The Geysers, in California","Old Faithful, in Wyoming","Niagara Falls"],"a":0,"why":"Despite the name, The Geysers has steam vents, not true geysers."},{"t":"mc","q":"Which country gets about 4 of every 10 units of its electricity from Earth heat?","c":["Kenya","Canada","Brazil"],"a":0,"why":"Kenya's plants sit in the Great Rift Valley, where the crust is pulling apart."},{"t":"mc","q":"How deep is the deepest hole people have ever drilled?","c":["About 12 kilometers","About 100 kilometers","All the way to the core"],"a":0,"why":"The Kola borehole in Russia stopped at about 12 kilometers. The center of the Earth is more than 6,000 kilometers down."},{"t":"mc","q":"Part of Earth's heat comes from atoms breaking down in the rock. That makes Earth heat a slow cousin of what?","c":["Nuclear power","Wind power","Solar power"],"a":0,"why":"The same kind of energy, released very slowly and spread through the whole planet."},{"t":"mc","q":"Engineers are testing ways to make Earth-heat power work in more places. What do they do?","c":["Drill into hot dry rock and pump water through cracks in it","Build taller chimneys","Wait for a volcano"],"a":0,"why":"A small one runs in Nevada, and the first full-size one started making power in Utah in 2026."}]],"zone":"geo"},{"id":"hotspot","name":"Hot Spot or Not?","blurb":"Where can Earth heat make electricity?","badge":"Hot Spot Scout","intro":["Earth heat is under every place, but only some places have very hot rock near the surface. Is this one of them?","Real places now.","What makes a hot spot, and what a mild spot can still do."],"levels":[[{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"A valley full of hot springs and geysers","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"Hot water at the surface means very hot rock is close below."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"A flat field in Ohio","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":1,"why":"The rock under Ohio is warm, but you would have to drill very deep to reach rock hot enough."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"A valley a few miles from a quiet old volcano","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"Hot rock is still close to the surface there."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"A sandy beach in Florida","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":1,"why":"There is no hot rock near the surface."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"An island with steaming vents in the ground","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"Steam at the surface is the best sign of all."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"A forest in Kentucky","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":1,"why":"Like Ohio, it sits far from any hot spot."}],[{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"Iceland","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"Iceland sits where two plates of the Earth's crust pull apart."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"Kansas","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":1,"why":"The middle of a plate is the calmest, coolest ground."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"The Great Rift Valley in Kenya","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"The crust is thin and stretching there."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"The Big Island of Hawaii","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"Hawaii sits over a hot spot, and a plant there taps that heat. In 2018 lava covered some of its wells and it had to close for a while. Very hot ground has costs too."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"New Zealand's North Island","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"It has volcanoes, geysers and several Earth-heat plants."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"The coast of the state of Georgia","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":1,"why":"There is no hot rock near the surface."},{"t":"mc","fixed":1,"pre":"A power plant that runs on Earth heat needs very hot rock close to the surface.","q":"Northern California near The Geysers","c":["Good place for an Earth-heat power plant","Poor place for one"],"a":0,"why":"It is the largest Earth-heat field in the world."}],[{"t":"mc","q":"What do most good places for Earth-heat power have in common?","c":["They sit near the edges of plates or over hot spots","They are near the equator","They are near big cities"],"a":0,"why":"That is where hot rock rises close to the surface."},{"t":"mc","q":"The ring of volcanoes around the Pacific Ocean is called what?","c":["The Ring of Fire","The Hot Belt","The Lava Loop"],"a":0,"why":"Japan, Indonesia, the Philippines, New Zealand and the west coast of the Americas all sit on it."},{"t":"mc","q":"Ohio cannot easily make electricity from Earth heat. What can a home in Ohio still do with the ground?","c":["Use a heat pump to heat and cool the house","Boil water for tea","Nothing"],"a":0,"why":"The mild, steady ground a few meters down works anywhere. That shallow warmth is mostly sunshine the ground has soaked up, not heat from deep inside."},{"t":"mc","q":"A ground heat pump moves about 3 to 5 units of heat for each unit of electricity it uses. How can that be?","c":["It moves heat that is already in the ground and does not make the heat itself","It breaks the energy rule","It burns hidden fuel"],"a":0,"why":"Moving heat takes less energy than making it. Nothing is created."},{"t":"mc","q":"Why not just drill 20 kilometers down, where rock is hot everywhere?","c":["Nobody can drill that deep yet, and each kilometer costs more than the last","It is against the rules","The rock is cold down there"],"a":0,"why":"The deepest hole ever drilled is about 12 kilometers."},{"t":"mc","q":"What is the best sign at the surface that hot rock is close below?","c":["Hot springs and steam vents","Tall trees","Sandy soil"],"a":0,"why":"People have bathed in hot springs for thousands of years."}]],"zone":"geo"},{"id":"geofair","name":"Good At, Costs","blurb":"What Earth heat does well and what it costs.","badge":"Fair Judge: Earth Heat","intro":["No energy source is perfect and none is the bad guy. Sort each fact about Earth heat.","More facts about Earth heat, good and costly.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It works day and night.","c":["Something it does well","Something it costs"],"a":0,"why":"The rock is just as hot at midnight."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It works in any weather.","c":["Something it does well","Something it costs"],"a":0,"why":"Clouds and calm air make no difference underground."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Only a few places have rock hot enough near the surface.","c":["Something it does well","Something it costs"],"a":1,"why":"Most of the world would have to drill very deep."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Nothing is burned.","c":["Something it does well","Something it costs"],"a":0,"why":"The heat is already there."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Drilling deep holes costs a lot.","c":["Something it does well","Something it costs"],"a":1,"why":"And a hole can turn out cooler than hoped."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A plant takes up little land.","c":["Something it does well","Something it costs"],"a":0,"why":"Most of it is underground."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It is steady, so it does not need a battery or a partner.","c":["Something it does well","Something it costs"],"a":0,"why":"It can run at nearly full power around the clock."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The hot water can warm buildings directly.","c":["Something it does well","Something it costs"],"a":0,"why":"Iceland heats most of its homes this way."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Some plants let out gases that smell like rotten eggs.","c":["Something it does well","Something it costs"],"a":1,"why":"Underground steam can carry a gas called hydrogen sulfide. Most plants catch it."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A drill can go down and find rock that is not hot enough.","c":["Something it does well","Something it costs"],"a":1,"why":"Then the money for that well is lost."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It adds very little carbon dioxide to the air.","c":["Something it does well","Something it costs"],"a":0,"why":"At most plants, far less than burning coal or gas."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"If a plant takes heat out too fast, the rock around its wells cools.","c":["Something it does well","Something it costs"],"a":1,"why":"The plant then has to slow down and let the heat creep back."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Pumping water into deep rock can set off small earthquakes.","c":["Something it does well","Something it costs"],"a":1,"why":"Most are too small to feel. A few have been strong enough to crack walls, and those projects were stopped. Projects now watch closely and slow down at the first sign."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A ground heat pump can heat and cool a home almost anywhere.","c":["Something it does well","Something it costs"],"a":0,"why":"It uses the mild ground, not hot rock."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The best sites are often far from the cities that need the power.","c":["Something it does well","Something it costs"],"a":1,"why":"Long power lines have to be built."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The heat will last for billions of years.","c":["Something it does well","Something it costs"],"a":0,"why":"The Earth is cooling far too slowly for anyone to notice."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A ground heat pump costs much more to put in than a furnace.","c":["Something it does well","Something it costs"],"a":1,"why":"The yard has to be dug or drilled for the pipes."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Old oil and gas drilling know-how can be used to build it.","c":["Something it does well","Something it costs"],"a":0,"why":"The same crews and drills can do both jobs."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Taking hot water out can make the ground above sink a little.","c":["Something it does well","Something it costs"],"a":1,"why":"Pumping the cooled water back down helps prevent it."}]],"zone":"geo"},{"id":"geoquiz","name":"Quick Quiz","blurb":"Five questions on Earth heat.","badge":"Earth Heat Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What happens to the temperature as you go deeper underground?","c":["It rises","It falls","It stays the same"],"a":0,"why":"Deeper is hotter."},{"t":"mc","q":"Which is the Earth's thin outer layer?","c":["The crust","The core","The mantle"],"a":0,"why":"We live on the crust."},{"t":"mc","q":"A hot spring gets its heat from where?","c":["Inside the Earth","The Sun","A fire"],"a":0,"why":"Hot rock warms the water."},{"t":"mc","q":"Does Earth heat work at night?","c":["Yes","No","Only in summer"],"a":0,"why":"It never switches off."},{"t":"mc","q":"What shoots hot water and steam into the air?","c":["A geyser","A river","A glacier"],"a":0,"why":"Old Faithful is the most famous one."}],[{"t":"mc","q":"About how hot does rock need to be to run a power plant well?","c":["About 150 degrees Celsius","About 15 degrees Celsius","About 15,000 degrees Celsius"],"a":0,"why":"Hot enough to make plenty of steam."},{"t":"mc","q":"Which country heats about 9 of every 10 homes with underground hot water?","c":["Iceland","Egypt","Australia"],"a":0,"why":"Iceland."},{"t":"mc","q":"Why does a power plant pump its cooled water back underground?","c":["So the hot rock can heat it again","To hide it","To water the plants"],"a":0,"why":"The same water goes around and around."},{"t":"mc","q":"Earth heat is steady. What does that mean?","c":["It makes about the same power all day and all night","It only works in steady rain","It is slow to build"],"a":0,"why":"It does not come and go like sun and wind."},{"t":"mc","q":"Why can Ohio not easily make electricity from Earth heat?","c":["The hot rock is too deep","Ohio is too cold","It rains too much"],"a":0,"why":"Five kilometers down it is still not hot enough."}],[{"t":"mc","q":"Rock is 10 degrees at the surface and warms 25 degrees for each kilometer. How hot is it 4 kilometers down?","c":["110 degrees","100 degrees","35 degrees"],"a":0,"why":"10 plus 4 times 25."},{"t":"mc","q":"Earth's inner heat is partly left from when the planet formed. Where does the rest come from?","c":["Atoms breaking down in the rock","The Moon","Ocean tides"],"a":0,"why":"That makes it a slow cousin of nuclear power."},{"t":"mc","q":"A ground heat pump gives out 4 units of heat for each unit of electricity. Where do the other 3 come from?","c":["The ground","Nowhere","The Sun, directly"],"a":0,"why":"It moves heat. It does not make it."},{"t":"mc","q":"What is the ring of volcanoes around the Pacific called?","c":["The Ring of Fire","The Rift","The Core"],"a":0,"why":"Many Earth-heat plants sit on it."},{"t":"mc","q":"How does the deepest hole ever drilled compare with the distance to the Earth's center?","c":["It is less than a hundredth of the way","It is halfway","It reached the center"],"a":0,"why":"About 12 kilometers out of more than 6,000."}]],"zone":"geo"}];
const CONTROL=[{"id":"grid","name":"Power the Town","blurb":"Mix sources to keep Brightwater's lights on all day.","badge":"Town Powerer","custom":"grid","intro":["This is the Control Room. Brightwater needs power morning, midday, evening and night. Pick sources until every part of the day is lit.","Now hour by hour, and the weather changes. Find a mix that keeps the lights on in sun, cloud and calm.","Now with megawatts and a budget. Your mix has to pass four test days and cost 85 coins or less."],"zone":"control"},{"id":"townday","name":"The Town's Day","blurb":"When a town needs the most power, and why.","badge":"Demand Reader","intro":["A town does not use the same amount of electricity all day. When does it need the most?","The words operators use: demand, supply and peak.","Megawatts, megawatt-hours and the shape of a day."],"levels":[[{"t":"mc","q":"When does a town use the least electricity?","c":["In the middle of the night","At dinnertime","At noon"],"a":0,"why":"Most people are asleep and most things are switched off."},{"t":"mc","q":"When does a town usually use the most?","c":["In the early evening","At 3 in the morning","At sunrise"],"a":0,"why":"People are home, cooking, with lights and screens on."},{"t":"mc","q":"What is still using electricity at 3 in the morning?","c":["Refrigerators, street lights and hospitals","Almost nothing","Only alarm clocks"],"a":0,"why":"Some things never switch off, so the need never drops to zero."},{"t":"mc","q":"On a hot summer afternoon, what uses a lot of electricity?","c":["Air conditioners","Heaters","Christmas lights"],"a":0,"why":"Cooling is one of the biggest uses of electricity in summer."},{"t":"mc","q":"Why does the need for power climb in the morning?","c":["People wake up, and shops, schools and factories start","The Sun pulls on the wires","Birds land on the lines"],"a":0,"why":"The climb starts at about 6 and levels off by 9."}],[{"t":"mc","q":"What do operators call the amount of electricity people are using?","c":["Demand","Supply","Voltage"],"a":0,"why":"Demand is what the town is asking for."},{"t":"mc","q":"What do they call the amount being made?","c":["Supply","Demand","Peak"],"a":0,"why":"Supply has to match demand."},{"t":"mc","q":"What is the highest demand of the day called?","c":["The peak","The valley","The gap"],"a":0,"why":"The lowest point is sometimes called the valley."},{"t":"mc","q":"In Ohio, which season has the highest peaks?","c":["Summer, because of air conditioning","Spring","Fall"],"a":0,"why":"The hottest afternoons of the year set the records."},{"t":"mc","q":"Why do power companies care so much about the peak?","c":["They must have enough ready for the biggest moment, even if it lasts an hour","It is the cheapest time","It is when they sleep"],"a":0,"why":"Whole power plants are kept ready for a few hot afternoons a year."},{"t":"mc","q":"What happens to demand on a holiday, when many offices and factories close?","c":["It drops","It doubles","Nothing"],"a":0,"why":"Fewer machines and lights are running."}],[{"t":"mc","q":"What is a megawatt?","c":["One million watts","One thousand watts","One hundred watts"],"a":0,"why":"Mega means million."},{"t":"mc","q":"About how many homes can one megawatt power at once?","c":["About 800","About 8","About 80,000"],"a":0,"why":"A typical American home uses a little over 1 kilowatt when you average the whole day."},{"t":"mc","q":"What is a megawatt-hour?","c":["One megawatt running for one hour","One megawatt running for one second","A very long hour"],"a":0,"why":"Megawatts say how fast. Megawatt-hours say how much."},{"t":"mc","q":"Brightwater needs 8 megawatts in the middle of the night and 18 at its peak. A plant that makes a steady 8 megawatts covers what?","c":["The middle of the night, and part of every other hour","The whole day","Only the peak"],"a":0,"why":"A steady source covers the bottom layer of the day. Other sources cover the rest."},{"t":"mc","q":"Electricity has to be made at the very moment it is used. What is the one way around that?","c":["Storing it","Making it faster","Using thicker wires"],"a":0,"why":"Batteries and pumped water are the main ways."},{"t":"mc","q":"Many people charge electric cars overnight. What does that do to the shape of the day?","c":["It raises the night valley","It raises the evening peak","Nothing"],"a":0,"why":"Using more at night can make the day's shape flatter and easier to supply."}]],"zone":"control"},{"id":"saveit","name":"Battery Bank","blurb":"Save power when there is extra. Use it when there is not.","badge":"Bank Manager","intro":["This is the Battery Bank. It cannot make energy. It saves what the other rooms make.","How a battery bank works through a day.","Two numbers describe a battery: how much it holds, and how fast it can give it back."],"levels":[[{"t":"mc","q":"Does a battery make energy?","c":["No. It stores energy that something else made","Yes, from nothing","Yes, from air"],"a":0,"why":"Energy is never made from nothing."},{"t":"mc","q":"A town has lots of solar panels. When should its batteries fill up?","c":["Around midday, when there is extra","At midnight","At dinnertime"],"a":0,"why":"Midday is when the panels make more than the town needs."},{"t":"mc","q":"When should those batteries give their power back?","c":["In the evening, after the Sun goes down","At noon","At sunrise"],"a":0,"why":"That is when the town needs the most and the panels make the least."},{"t":"mc","q":"What in the Wheel Room works like a battery?","c":["The reservoir behind the dam","The fish ladder","The spillway"],"a":0,"why":"Water held up high is stored energy."},{"t":"mc","q":"A battery is empty. What can it do for the town?","c":["Nothing, until it is charged again","Run the town for a day","Make sunlight"],"a":0,"why":"A battery only gives back what was put in."}],[{"t":"mc","q":"The Sun and wind are making more than the town needs. What does the Battery Bank do?","c":["It charges","It empties","It switches off the town"],"a":0,"why":"It soaks up the extra."},{"t":"mc","q":"The bank is full and there is still extra power. What happens to the extra?","c":["It is wasted, or a source is turned down","It is saved anyway","It runs backward"],"a":0,"why":"This is why operators do not want far more sources than they can use or store."},{"t":"mc","q":"A battery gives back a little less than was put in. Where did the rest go?","c":["It became heat","It disappeared","It leaked out as electricity"],"a":0,"why":"About 10 to 20 of every 100 units are lost as heat."},{"t":"mc","q":"A battery bank can run the town for 4 hours. What happens in hour 5?","c":["It is empty, and something else has to take over","It keeps going","It runs faster"],"a":0,"why":"Storage buys time. It does not replace a source."},{"t":"mc","q":"What is the oldest kind of big energy storage on the grid?","c":["Water pumped uphill","Giant springs","Hot rocks"],"a":0,"why":"You met it in the Wheel Room."}],[{"t":"mc","q":"What do megawatt-hours tell you about a battery?","c":["How much energy it holds","How fast it can give energy","How heavy it is"],"a":0,"why":"It is the size of the tank."},{"t":"mc","q":"What do megawatts tell you about a battery?","c":["How fast it can give energy","How much energy it holds","How old it is"],"a":0,"why":"It is the width of the tap."},{"t":"mc","q":"A battery holds 8 megawatt-hours and can give 4 megawatts. How long does it last at full power?","c":["2 hours","4 hours","32 hours"],"a":0,"why":"8 divided by 4."},{"t":"mc","q":"How long can most big grid batteries run at full power?","c":["A few hours","A few weeks","A few seconds"],"a":0,"why":"Two to four hours is common today. Brightwater has 2-hour batteries."},{"t":"mc","q":"Which of these is hardest to cover with batteries alone?","c":["A calm, cloudy week","One evening","One minute"],"a":0,"why":"Batteries are built for hours, not for a week."},{"t":"mc","q":"A battery returns 90 of every 100 units put in. You store 50 megawatt-hours. How much comes back?","c":["45","50","40"],"a":0,"why":"Nine tenths of 50."}]],"zone":"control"},{"id":"rightsrc","name":"Right Source for the Job","blurb":"Match each source to what it is good at.","badge":"Mix Master","intro":["You have met four sources. Each has its own strengths. Which one is this?","More about what each source can and cannot do.","Now you are the operator. What would you do?"],"levels":[[{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It makes the most around the middle of the day.","c":["Sun","Wind","Water","Earth heat"],"a":0,"why":"Its power follows the Sun across the sky."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It can make power at night, if the air is moving.","c":["Sun","Wind","Water","Earth heat"],"a":1,"why":"Wind does not need daylight."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It makes the same amount all day and all night, whatever the weather, with nobody turning it up or down.","c":["Sun","Wind","Water","Earth heat"],"a":3,"why":"The rock is always hot."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It can wait behind a dam until it is needed.","c":["Sun","Wind","Water","Earth heat"],"a":2,"why":"A reservoir stores energy."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It makes nothing after sunset.","c":["Sun","Wind","Water","Earth heat"],"a":0,"why":"No light, no power."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It stops when the air is calm.","c":["Sun","Wind","Water","Earth heat"],"a":1,"why":"No wind, no power."}],[{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It can go from off to full power in a few minutes.","c":["Sun","Wind","Water","Earth heat"],"a":2,"why":"Operators only have to open the gate."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It needs very hot rock near the surface.","c":["Sun","Wind","Water","Earth heat"],"a":3,"why":"That is why it suits only some places."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It fits on a rooftop.","c":["Sun","Wind","Water","Earth heat"],"a":0,"why":"Panels can sit on roofs that were empty anyway."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"Its power grows 8 times when the air moves twice as fast.","c":["Sun","Wind","Water","Earth heat"],"a":1,"why":"2 × 2 × 2 = 8."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It runs low in a drought.","c":["Sun","Wind","Water","Earth heat"],"a":2,"why":"Less rain, less water behind the dam."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It is often stronger at night, and in the cooler months.","c":["Sun","Wind","Water","Earth heat"],"a":1,"why":"That makes it a good partner for the Sun."},{"t":"mc","fixed":1,"pre":"Which source fits this description best?","q":"It is strongest in summer.","c":["Sun","Wind","Water","Earth heat"],"a":0,"why":"Long days and a high Sun."}],[{"t":"mc","q":"It is a still, cloudy evening. Which sources can still help?","c":["Water and Earth heat","Sun and wind","None of them"],"a":0,"why":"They do not depend on the weather of the day."},{"t":"mc","q":"It is noon, sunny and breezy, and the batteries are full. What should the operators do with the dam?","c":["Close the gate and save the water for the evening","Open it wide","Drain it"],"a":0,"why":"Water is the one source here that can wait."},{"t":"mc","q":"It is night, the wind is strong and the town is asleep. There is more power than the town needs. What is the best use for it?","c":["Charge batteries or pump water uphill","Run every toaster in town","Let it go to waste"],"a":0,"why":"Spare power is worth saving for the next peak."},{"t":"mc","q":"Which pair of sources covers each other's weak times best in many places?","c":["Sun and wind","Sun and more Sun","Wind and more wind"],"a":0,"why":"One is often strong when the other is weak."},{"t":"mc","q":"A town has plenty of solar panels and one big dam. When should it use the dam most?","c":["In the evening and at night","At noon","Never"],"a":0,"why":"Let the Sun carry the day and save the water for the dark hours."},{"t":"mc","q":"Why not build only the cheapest source and lots of it?","c":["No single source covers every hour of every day","It would look boring","It is against the rules"],"a":0,"why":"A mix is safer than any one source."}]],"zone":"control"},{"id":"balance","name":"Keeping the Balance","blurb":"Supply has to match demand, every second.","badge":"Grid Balancer","intro":["The power being made has to match the power being used. Here is how that works.","The grid, and the people who run it.","How operators keep the balance to a fraction of a second."],"levels":[[{"t":"mc","q":"For the lights to stay on, the power being made must do what?","c":["Match what the town is using","Be as large as possible","Be made only at night"],"a":0,"why":"Too little, and lights go out. Too much, and a source has to be turned down."},{"t":"mc","q":"What happens when a town has too little power?","c":["Some lights and machines go off","Everything runs faster","Nothing"],"a":0,"why":"There is not enough to go around."},{"t":"mc","q":"What is a power outage also called?","c":["A blackout","A sunburn","A heat wave"],"a":0,"why":"Most outages are caused by storms damaging lines, not by a lack of power."},{"t":"mc","q":"What do people call all the power plants, wires and poles joined together?","c":["The grid","The web","The loop"],"a":0,"why":"It is one of the largest machines people have ever built."},{"t":"mc","q":"Who decides how much power to make from minute to minute?","c":["Operators in a control room, helped by computers","Each family","Nobody"],"a":0,"why":"They watch demand and adjust supply to match."}],[{"t":"mc","q":"Towns are joined to each other by power lines. Why does that help?","c":["A town that is short can get power from one that has extra","It makes the wires prettier","It makes electricity heavier"],"a":0,"why":"The weather is rarely bad everywhere at once."},{"t":"mc","q":"Who keeps the grid in balance for Ohio and a dozen other states?","c":["A grid operator called PJM","The Mayor of Cincinnati","NASA"],"a":0,"why":"PJM serves more than 65 million people from Illinois to New Jersey."},{"t":"mc","q":"Long-distance power lines carry electricity at a very high push. Why?","c":["Less energy is lost as heat along the way","It is quieter","It keeps birds warm"],"a":0,"why":"Higher volts mean fewer amps for the same power, and fewer amps heat the wire less."},{"t":"mc","q":"What does the gray can on a pole, or the green box on the ground, near your home do?","c":["It lowers the push to a level a house can use","It makes electricity","It stores it"],"a":0,"why":"It is a transformer. It steps thousands of volts down to 120 and 240. Never climb on or open one."},{"t":"mc","q":"Everyone turns on air conditioning at once. What do operators do?","c":["Bring more sources online","Turn off the Sun","Wait until winter"],"a":0,"why":"Sources that can start quickly are the most useful at that moment."}],[{"t":"mc","q":"The current in American outlets swings back and forth. How many full back-and-forth swings does it make each second?","c":["60","6","6,000"],"a":0,"why":"It is called 60 hertz. Operators keep it very close to exactly 60."},{"t":"mc","q":"Demand suddenly jumps above supply. What happens to that 60?","c":["It dips slightly, and that is how operators see the problem","It doubles","Nothing"],"a":0,"why":"The generators slow a tiny bit under the extra load."},{"t":"mc","q":"What are the spare sources called that wait, ready to start?","c":["Reserves","Leftovers","Backups of backups"],"a":0,"why":"Operators always keep some ready."},{"t":"mc","q":"Sometimes big users are paid to use less at peak times. What is that called?","c":["Demand response","Supply surprise","Power nap"],"a":0,"why":"Lowering demand can balance the grid just as raising supply can."},{"t":"mc","q":"Why do grids have more sources than they need on an ordinary day?","c":["The extra is what keeps the lights on during the hardest days","By mistake","To use up coins"],"a":0,"why":"You design for the worst day, not the average one."},{"t":"mc","q":"About how much of the time does the grid deliver power to a typical American home?","c":["More than 99 of every 100 hours","About 90 of every 100 hours","About half the time"],"a":0,"why":"In an ordinary year a typical home loses power for only a few hours in total. A year with big storms can be worse."}]],"zone":"control"},{"id":"gridquiz","name":"Quick Quiz","blurb":"Five questions on running a grid.","badge":"Grid Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"When does a town need the most power?","c":["Early evening","Middle of the night","Sunrise"],"a":0,"why":"People are home and busy."},{"t":"mc","q":"Which source makes nothing at night?","c":["Sun","Wind","Earth heat"],"a":0,"why":"The Sun is down."},{"t":"mc","q":"What does a battery do?","c":["It stores energy for later","It makes energy","It uses up energy"],"a":0,"why":"It saves what another source made."},{"t":"mc","q":"Why does a town need more than one kind of source?","c":["Each is strong at different times","One kind is not allowed","For decoration"],"a":0,"why":"A mix covers the whole day."},{"t":"mc","q":"What is the grid?","c":["The power plants and wires all joined together","A kind of battery","A solar panel"],"a":0,"why":"It connects every source to every user."}],[{"t":"mc","q":"What is demand?","c":["How much electricity people are using","How much is being made","How much is stored"],"a":0,"why":"Supply has to match it."},{"t":"mc","q":"What is the highest demand of the day called?","c":["The peak","The base","The gap"],"a":0,"why":"The peak."},{"t":"mc","q":"Which source can best wait and then start in minutes?","c":["Water","Sun","Wind"],"a":0,"why":"Open the gate and it runs."},{"t":"mc","q":"The batteries are full and there is still extra power. What happens to it?","c":["It is wasted or a source is turned down","It is stored anyway","It makes the lights brighter"],"a":0,"why":"Storage has a limit."},{"t":"mc","q":"Why test a mix on a cloudy day and a calm day too?","c":["The town needs power in every kind of weather","For fun","Cloudy days are cheaper"],"a":0,"why":"A mix has to work on its worst day."}],[{"t":"mc","q":"One megawatt is how many watts?","c":["1,000,000","1,000","100"],"a":0,"why":"A million."},{"t":"mc","q":"A battery holds 12 megawatt-hours and gives 4 megawatts. How long does it last?","c":["3 hours","8 hours","48 hours"],"a":0,"why":"12 divided by 4."},{"t":"mc","q":"Which source here gives the same power on all four test days?","c":["Earth heat","Sun","Wind"],"a":0,"why":"It does not care about weather."},{"t":"mc","q":"A mix that wastes nothing on the best day will usually do what on the worst day?","c":["Run short","Cost less","Run better"],"a":0,"why":"Being ready for bad days means having extra on good ones."},{"t":"mc","q":"What keeps to 60 in the American grid?","c":["The number of back-and-forth swings the current makes each second","The number of power plants","The price"],"a":0,"why":"60 hertz."}]],"zone":"control"}];
const FOOD=[{"id":"pedal","name":"Pedal Power Lab","blurb":"How many riders does it take to run a toaster?","badge":"Pedal Pusher","custom":"pedal","intro":["This bike is wired to a generator, a machine that makes electricity when it spins. Whoever pedals makes electricity out of breakfast. Follow the job card.","Three kinds of rider: a kid, a grown-up and a bike racer. Find how many of each it takes to run a toaster.","Now count the energy: how much one hour of pedaling makes, what it is worth, and how much food it takes."],"zone":"food"},{"id":"fuel","name":"Snack Power","blurb":"Pick a food and an activity. How long does the fuel last?","badge":"Fuel Reader","custom":"fuel","intro":["Food is your fuel. Pick a food and something to do, and see how long that fuel would last.","Your body uses fuel at different speeds. Find a food and an activity that last about an hour.","Food energy is counted in Calories. Work out the numbers."],"zone":"food"},{"id":"foodchain","name":"Sun to Supper","blurb":"Put the links in order, from the Sun to your plate.","badge":"Food Tracer","intro":["Every food chain starts with a plant catching sunlight. Tap the links in order.","Longer chains, from the sea and from the hive.","What happens inside a muscle."],"levels":[[{"t":"order","q":"A glass of milk","links":[["Sunshine","glow"],["Grass grows","stash"],["A cow eats the grass","stash"],["You drink the milk","stash"]],"why":"The energy in milk started as sunlight on a field."},{"t":"order","q":"A bike ride","links":[["Sunshine","glow"],["Wheat grows","stash"],["Wheat becomes bread","stash"],["You eat toast and pedal","zip"]],"why":"Stored energy became motion."},{"t":"order","q":"An apple","links":[["Sunshine","glow"],["The apple tree grows leaves","stash"],["The tree packs sugar into apples","stash"],["You eat one and climb the stairs","zip"]],"why":"A tree stores sunlight as sugar."}],[{"t":"order","q":"A tuna sandwich","links":[["Sunlight reaches the sea","glow"],["Tiny floating plants grow","stash"],["Small fish eat them","stash"],["A tuna eats the small fish","stash"],["You eat the sandwich","stash"]],"why":"Even food from the deep sea starts with sunlight at the surface."},{"t":"order","q":"Honey on toast","links":[["Sunshine","glow"],["Flowers make sweet nectar","stash"],["Bees turn nectar into honey","stash"],["You spread it on toast","stash"]],"why":"Honey is sunlight that passed through a flower and a bee."},{"t":"order","q":"Warm hands after a run","links":[["You eat breakfast","stash"],["Your muscles use the food to move","zip"],["Most of that energy becomes heat","ember"],["Your blood carries the heat to your skin","ember"]],"why":"Moving makes heat. That is why exercise warms you up."}],[{"t":"order","q":"Inside a muscle","links":[["Food is broken down into sugar","stash"],["Blood carries sugar and oxygen to the muscle","zip"],["The muscle joins them and releases energy","ember"],["The muscle pulls and you move","zip"],["You breathe out the carbon dioxide","zip"]],"why":"It is a very slow, cool kind of burning."},{"t":"order","q":"From a field to a pedal-powered lamp","links":[["Sunlight","glow"],["Wheat","stash"],["Bread","stash"],["Leg muscles","zip"],["A spinning generator","spark"],["A lit bulb","glow"]],"why":"Light went in at the field and came out at the bulb."},{"t":"order","q":"A bear in winter","links":[["Summer berries and fish","stash"],["The bear stores fat in autumn","stash"],["It sleeps through winter, slowly using the fat to stay warm","ember"],["It wakes up thin in spring","zip"]],"why":"Body fat is an energy store, like a battery."}]],"zone":"food"},{"id":"engine","name":"Body Engine","blurb":"What your body does with the energy in food.","badge":"Engine Expert","intro":["Your body is an engine and food is its fuel. What does the engine do with it?","How the body gets energy out of food.","Numbers for the body engine."],"levels":[[{"t":"mc","q":"Where does your body get its energy?","c":["From food","From water","From air alone"],"a":0,"why":"You need water and air too, but the energy comes from food."},{"t":"mc","q":"What does your body use energy for?","c":["Moving, growing, keeping warm and thinking","Only running","Only eating"],"a":0,"why":"It uses energy for everything it does."},{"t":"mc","q":"After you run, you feel warm. Why?","c":["Your muscles turn part of the food energy into heat","The air got hotter","Your shoes rubbed"],"a":0,"why":"Working muscles make a lot of heat."},{"t":"mc","q":"Which of these needs energy even while you sleep?","c":["Your heart","Your bike","Your shoes"],"a":0,"why":"Your heart, lungs and brain never stop."},{"t":"mc","q":"Where did the energy in an apple come from?","c":["Sunlight the tree caught","The soil","The grocery store"],"a":0,"why":"Soil gives the tree water and minerals. The energy comes from the Sun."}],[{"t":"mc","q":"What unit is the energy in food counted in?","c":["Calories","Volts","Degrees"],"a":0,"why":"It is the unit scientists use for the fuel in food."},{"t":"mc","q":"To get the energy out of food, what else does your body need?","c":["Oxygen from the air you breathe","Sunlight on your skin","Electricity"],"a":0,"why":"That is why you breathe harder when you exercise."},{"t":"mc","q":"About what temperature does your body keep itself at?","c":["About 98.6 degrees Fahrenheit","About 50 degrees Fahrenheit","About 150 degrees Fahrenheit"],"a":0,"why":"It holds that temperature in summer and in winter, and that takes energy."},{"t":"mc","q":"Of the food energy a muscle uses, about how much becomes motion?","c":["About a quarter. The rest becomes heat","All of it","Almost none"],"a":0,"why":"Car engines are about the same."},{"t":"mc","q":"Which animal has to eat the most for its size?","c":["A hummingbird","An elephant","A tortoise"],"a":0,"why":"Small warm animals lose heat fast. A hummingbird may visit a thousand flowers in a day."},{"t":"mc","q":"A bear sleeps through the winter without eating. What does it run on?","c":["Fat it stored in autumn","Snow","Nothing at all"],"a":0,"why":"Fat is stored energy."}],[{"t":"mc","q":"One food Calorie is how many joules?","c":["About 4,184","About 4","About 4 million"],"a":0,"why":"A food Calorie is a big unit. It could warm a liter of water by one degree Celsius."},{"t":"mc","q":"A gram of fat stores how much energy compared with a gram of sugar?","c":["More than twice as much","The same","Half as much"],"a":0,"why":"About 9 Calories against about 4. That is why animals store energy as fat."},{"t":"mc","q":"Only about a tenth of the energy at one step of a food chain reaches the next. Grass holds 1,000 units. A cow eats it, and a person drinks the milk. About how much reaches the person?","c":["About 10 units","About 500 units","About 1,000 units"],"a":0,"why":"About 100 reach the cow and about 10 reach the person. The rest kept the grass and the cow alive."},{"t":"mc","q":"A grown-up sitting still gives off heat about as fast as what?","c":["One old-style 100-watt light bulb","A toaster","A power plant"],"a":0,"why":"A room full of people warms up for that reason."},{"t":"mc","q":"About how much of a resting grown-up's energy does the brain use?","c":["About a fifth","About a hundredth","Nearly all of it"],"a":0,"why":"A child's brain uses an even bigger share, because it is still growing."},{"t":"mc","q":"What does your body breathe out after it gets energy from food?","c":["Carbon dioxide and water vapor","Oxygen","Smoke"],"a":0,"why":"The same two things a candle gives off, made far more slowly."}]],"zone":"food"},{"id":"musclefair","name":"Good At, Costs","blurb":"What muscle power does well and what it costs.","badge":"Fair Judge: Muscle","intro":["No energy source is perfect and none is the bad guy. Sort each fact about muscle power.","More facts about muscle power, for people and for animals.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It is always with you.","c":["Something it does well","Something it costs"],"a":0,"why":"You carry your engine everywhere."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It needs no wires.","c":["Something it does well","Something it costs"],"a":0,"why":"A bike works on any road."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It gets tired.","c":["Something it does well","Something it costs"],"a":1,"why":"Muscles need rest."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes only a little power.","c":["Something it does well","Something it costs"],"a":1,"why":"One person makes about as much as one bright old light bulb uses."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It is quiet and makes no smoke.","c":["Something it does well","Something it costs"],"a":0,"why":"Nothing is burned outside the body."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It cannot run a house.","c":["Something it does well","Something it costs"],"a":1,"why":"A house needs the power of dozens of people, day and night."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A bicycle carries a person farther on a snack than walking or running.","c":["Something it does well","Something it costs"],"a":0,"why":"A bike wastes very little of your effort."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A horse can work about ten times as hard as a person.","c":["Something it does well","Something it costs"],"a":0,"why":"For thousands of years, horses and oxen did the heaviest farm work."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A working animal has to be fed every day, working or not.","c":["Something it does well","Something it costs"],"a":1,"why":"An engine uses no fuel while it is switched off."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Growing the food takes farmland.","c":["Something it does well","Something it costs"],"a":1,"why":"A good share of old farms grew feed for the horses."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Exercise keeps the body healthy.","c":["Something it does well","Something it costs"],"a":0,"why":"Your engine gets stronger the more you use it."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Hard work by muscle is slow.","c":["Something it does well","Something it costs"],"a":1,"why":"A field that took a team of horses days can be plowed by a tractor in hours."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Making one kilowatt-hour takes a kid about 25 hours of pedaling.","c":["Something it does well","Something it costs"],"a":1,"why":"The grid delivers the same energy for about 18 cents."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A hand crank or pedals can run a radio or charge a phone where there is no grid.","c":["Something it does well","Something it costs"],"a":0,"why":"Crank radios are sold for emergencies."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Energy from food costs far more than the same energy from the wall.","c":["Something it does well","Something it costs"],"a":1,"why":"Food is worth it for other reasons."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A person on a bicycle uses less energy for each mile than a person driving any car.","c":["Something it does well","Something it costs"],"a":0,"why":"A bike and rider weigh far less than a car."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Before engines, how much land a farm could plow and how much a crew could build was limited by muscle.","c":["Something it does well","Something it costs"],"a":1,"why":"Engines changed what people could build."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Muscles can start, stop and change speed in an instant.","c":["Something it does well","Something it costs"],"a":0,"why":"No switch and no waiting."}]],"zone":"food"},{"id":"foodquiz","name":"Quick Quiz","blurb":"Five questions on food and muscle.","badge":"Muscle Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What is your body's fuel?","c":["Food","Socks","Shoes"],"a":0,"why":"Food stores energy."},{"t":"mc","q":"Where does the energy in food start?","c":["With sunlight on a plant","In the kitchen","In a factory"],"a":0,"why":"Plants catch it first."},{"t":"mc","q":"Does your body use energy when you sleep?","c":["Yes","No","Only on school nights"],"a":0,"why":"Your heart, lungs and brain keep working."},{"t":"mc","q":"Why do you get warm when you run?","c":["Muscles make heat as they work","The ground is hot","Running makes sunshine"],"a":0,"why":"Most of the energy a muscle uses becomes heat."},{"t":"mc","q":"Can one kid on a bike run a toaster?","c":["No. It takes about 25 kids","Yes, easily","Yes, if she is hungry"],"a":0,"why":"A toaster needs about 1,000 watts."}],[{"t":"mc","q":"About how many watts can a kid your age pedal steadily?","c":["About 40","About 400","About 4,000"],"a":0,"why":"And about twice that, flat out, for a minute or two."},{"t":"mc","q":"What is food energy counted in?","c":["Calories","Watts","Amps"],"a":0,"why":"Calories."},{"t":"mc","q":"What does your body need, besides food, to get energy?","c":["Oxygen","Helium","Moonlight"],"a":0,"why":"You breathe it in."},{"t":"mc","q":"Most of the energy you use in a day goes to what?","c":["Staying alive: heartbeat, breathing, warmth, growing and thinking","Running and jumping","Talking"],"a":0,"why":"That is true even on a busy day."},{"t":"mc","q":"Where does a bear's winter energy come from?","c":["Stored fat","Stored snow","The Sun"],"a":0,"why":"Fat is an energy store."}],[{"t":"mc","q":"A kid pedals at 40 watts for one hour. How much energy is that?","c":["40 watt-hours","40 kilowatt-hours","4,000 watt-hours"],"a":0,"why":"Watts times hours."},{"t":"mc","q":"One food Calorie is about how many joules?","c":["4,184","41","4 million"],"a":0,"why":"About 4,184."},{"t":"mc","q":"About how much of the energy a muscle uses becomes motion?","c":["About a quarter","Nearly all","Almost none"],"a":0,"why":"The rest becomes heat."},{"t":"mc","q":"About how much energy passes from one step of a food chain to the next?","c":["About a tenth","About half","All of it"],"a":0,"why":"The rest kept the plant or animal alive."},{"t":"mc","q":"One horsepower is about how many watts?","c":["About 750","About 75","About 7,500"],"a":0,"why":"A grown-up working all day long can keep up about a tenth of that."}]],"zone":"food"}];
const FOSSIL=[{"id":"boiler","name":"Boiler Lab","blurb":"Feed the fire, raise steam, spin the turbine, light the town.","badge":"Steam Raiser","custom":"boiler","intro":["This is a steam power plant. Fuel burns, water boils, steam spins a turbine. Follow the job card.","Two fuels, coal and natural gas. Light the same town with each and compare.","Now count the energy that goes in and the energy that comes out."],"zone":"fossil"},{"id":"fossilchain","name":"Buried Sunshine","blurb":"Put the links in order, from an ancient swamp to a lamp.","badge":"Deep Time Tracer","intro":["Coal, oil and gas are sunlight that plants and tiny sea life caught long ago. Tap the links in order.","Longer chains, for oil and for gas.","The whole trip, and where the carbon goes."],"levels":[[{"t":"order","q":"How coal formed","links":[["Sunlight falls on a swamp forest","glow"],["Giant plants grow","stash"],["Dead plants pile up under water and mud","stash"],["Millions of years of squeezing turn them to coal","stash"]],"why":"Coal is ancient plants, pressed into rock."},{"t":"order","q":"From coal to a lamp","links":[["Coal burns","ember"],["Water boils into steam","ember"],["Steam spins a turbine","zip"],["A generator makes electricity","spark"],["A lamp lights","glow"]],"why":"Stored energy became heat, then motion, then electricity, then light."},{"t":"order","q":"A car trip","links":[["Oil is pumped from deep underground","stash"],["A factory called a refinery makes gasoline","stash"],["Gasoline burns inside the engine","ember"],["The wheels turn","zip"]],"why":"Stored energy became heat, then motion."}],[{"t":"order","q":"How oil formed","links":[["Sunlight reaches an ancient sea","glow"],["Tiny floating plants and animals grow","stash"],["They sink and are buried in mud","stash"],["Heat and pressure slowly cook them into oil","stash"],["Oil collects in tiny holes in the rock","stash"]],"why":"Oil is mostly tiny sea life, not dinosaurs."},{"t":"order","q":"Natural gas to a warm house","links":[["A well reaches gas deep in rock","stash"],["Pipes carry the gas under the streets","zip"],["A furnace burns it","ember"],["Warm air flows through the rooms","ember"]],"why":"Gas can be burned right where the heat is needed."},{"t":"order","q":"A plastic bottle","links":[["Ancient sea life","stash"],["Oil and gas underground","stash"],["A factory turns part of it into plastic pellets","stash"],["Pellets are melted and blown into a bottle","ember"]],"why":"Plastic is made from oil and gas. Not all of it is burned."}],[{"t":"order","q":"Where the carbon goes","links":[["Ancient plants take carbon dioxide from the air","glow"],["The carbon is buried as coal for 300 million years","stash"],["A power plant burns the coal","ember"],["The carbon goes back into the air as carbon dioxide","ember"],["The extra carbon dioxide holds in more of Earth's heat","ember"]],"why":"Burning puts back in a few hundred years what plants took out over millions."},{"t":"order","q":"A gas power plant with two turbines","links":[["Gas burns and the hot gases spin the first turbine","zip"],["The leftover heat boils water","ember"],["The steam spins a second turbine","zip"],["Both turn generators","spark"]],"why":"Using the heat twice is why a modern gas plant wastes less."},{"t":"order","q":"From sunlight to a moving ship, the long way","links":[["Sunlight, long ago","glow"],["Sea life","stash"],["Oil","stash"],["Fuel burning in an engine","ember"],["A turning propeller","zip"]],"why":"Many millions of years passed between the first link and the last."}]],"zone":"fossil"},{"id":"fossilfacts","name":"Fuel Facts","blurb":"What coal, oil and gas are, and what happens when they burn.","badge":"Fuel Scholar","intro":["Three fuels from deep in the ground. What do you know about them?","How they formed and how we use them.","Numbers for the fuels."],"levels":[[{"t":"mc","q":"What are coal, oil and natural gas made from?","c":["Plants and tiny sea life from long ago","Melted rock","Old dinosaurs only"],"a":0,"why":"Coal is mostly swamp plants. Oil and gas are mostly tiny sea life."},{"t":"mc","q":"Why are they called fossil fuels?","c":["They formed from living things buried long ago","They are found inside dinosaur bones","They are very hard"],"a":0,"why":"A fossil is what is left of something that lived long ago."},{"t":"mc","q":"Where did their energy first come from?","c":["The Sun","The center of the Earth","The Moon"],"a":0,"why":"Plants and sea life caught sunlight. The fuel still holds it."},{"t":"mc","q":"What do we have to do to get the energy out?","c":["Burn them","Freeze them","Shake them"],"a":0,"why":"Burning turns the stored energy into heat."},{"t":"mc","q":"Which one is a black rock?","c":["Coal","Oil","Natural gas"],"a":0,"why":"Oil is a liquid and natural gas is a gas."},{"t":"mc","q":"What gas goes into the air when they burn?","c":["Carbon dioxide","Helium","Oxygen"],"a":0,"why":"Burning uses up oxygen and makes carbon dioxide and water."}],[{"t":"mc","q":"About how long ago did Ohio's coal form?","c":["About 300 million years ago","About 300 years ago","About 3,000 years ago"],"a":0,"why":"That is before the first dinosaurs. Some coal out West is much younger."},{"t":"mc","q":"Can we make more coal when we run out?","c":["Not in any time that helps us. It takes millions of years","Yes, in a factory in a week","Yes, by planting trees this year"],"a":0,"why":"That is why fossil fuels are called nonrenewable."},{"t":"mc","q":"Natural gas has no smell. Why does the gas in a stove smell like rotten eggs?","c":["A smell is added on purpose so people notice a leak","It rots in the pipes","It comes from eggs"],"a":0,"why":"If you ever smell it, do not touch any switches. Tell a grown-up right away and go outside together."},{"t":"mc","q":"What is natural gas mostly made of?","c":["Methane","Steam","Oxygen"],"a":0,"why":"Methane is one carbon atom and four hydrogen atoms."},{"t":"mc","q":"Which of these is made from oil?","c":["Gasoline, jet fuel and most plastic","Glass","Steel"],"a":0,"why":"A refinery sorts oil into many products."},{"t":"mc","q":"What machines did coal power first, about 250 years ago?","c":["Steam engines in mines and mills","Light bulbs","Cars"],"a":0,"why":"Steam engines came long before electric lights."}],[{"t":"mc","q":"About how much of the energy people use in the world still comes from fossil fuels?","c":["About four fifths","About one tenth","All of it"],"a":0,"why":"That counts cars, planes, factories and heat, not just electricity."},{"t":"mc","q":"For the same electricity, how does carbon dioxide from a gas plant compare with a coal plant?","c":["Less than half as much","Twice as much","Exactly the same"],"a":0,"why":"Gas has less carbon for its energy, and gas plants waste less heat."},{"t":"mc","q":"In Ohio, which fuel makes the most electricity today?","c":["Natural gas","Coal","Oil"],"a":0,"why":"Coal was first for many years. Gas passed it."},{"t":"mc","q":"A coal power plant turns about how much of the coal's energy into electricity?","c":["About a third","Nearly all","About a hundredth"],"a":0,"why":"The rest leaves as heat."},{"t":"mc","q":"A gallon of gasoline holds about 33,700 watt-hours. A kid pedaling makes 40 watt-hours in an hour. About how long would the kid pedal to match one gallon?","c":["About 840 hours","About 84 hours","About 8 hours"],"a":0,"why":"Fuels pack a huge amount of energy into a small space. That is why they are so useful."},{"t":"mc","q":"Why does extra carbon dioxide in the air matter?","c":["It holds in more of Earth's heat, so the climate warms","It makes the sky darker","It uses up the wind"],"a":0,"why":"Earth Lab calls it the greenhouse blanket."}]],"zone":"fossil"},{"id":"fuelwhich","name":"Which Fuel?","blurb":"Match each job to the fuel that usually does it.","badge":"Fuel Detective","intro":["Coal, oil or natural gas? Pick the fuel that usually does each job.","More jobs, and a few surprises.","Why each fuel fits its job."],"levels":[[{"t":"mc","q":"What do most cars with engines burn?","c":["Gasoline, made from oil","Coal","Natural gas"],"a":0,"why":"A liquid fuel is easy to carry in a tank."},{"t":"mc","q":"What burns with a blue flame on a gas kitchen stove?","c":["Natural gas","Coal","Gasoline"],"a":0,"why":"It comes to the house in a pipe."},{"t":"mc","q":"What did old steam trains burn?","c":["Coal","Natural gas","Jet fuel"],"a":0,"why":"A worker shoveled it into the firebox."},{"t":"mc","q":"What do jet planes burn?","c":["Jet fuel, made from oil","Coal","Wood"],"a":0,"why":"It is a lot like lamp oil."},{"t":"mc","q":"What heats many homes in Ohio in winter?","c":["Natural gas","Coal","Gasoline"],"a":0,"why":"A furnace burns it in the basement."}],[{"t":"mc","q":"A backyard grill with a tank burns what?","c":["Propane, which comes from oil and gas wells","Coal dust","Gasoline"],"a":0,"why":"Propane is squeezed into a liquid so a lot fits in the tank."},{"t":"mc","q":"Which fuel is burned in a blast furnace to help turn iron ore into steel?","c":["Coal, baked into coke","Natural gas only","Gasoline"],"a":0,"why":"Steel mills are one of coal's biggest jobs."},{"t":"mc","q":"Big trucks and trains mostly burn what?","c":["Diesel, made from oil","Coal","Propane"],"a":0,"why":"Diesel engines are strong and waste less fuel."},{"t":"mc","q":"Most of the fossil fuel burned to make electricity in the world is what?","c":["Coal","Gasoline","Jet fuel"],"a":0,"why":"Natural gas is second."},{"t":"mc","q":"Which of these is made from oil but is not burned?","c":["Plastic toys","Smoke","Steam"],"a":0,"why":"Tires, paint and many fabrics start as oil too."}],[{"t":"mc","q":"Why do planes use liquid fuel and not coal?","c":["Liquid fuel holds a lot of energy for its weight and flows through pipes","Coal is too clean","Coal is too cold"],"a":0,"why":"Weight matters most when you have to lift it."},{"t":"mc","q":"Why can a gas power plant help on a day when the wind drops?","c":["It can start and speed up quickly","It makes wind","It stores sunlight"],"a":0,"why":"Some gas plants reach full power in minutes."},{"t":"mc","q":"Why is coal mostly used close to railroads and rivers?","c":["It is heavy and bulky, so it moves by train and barge","It floats away","It melts in trucks"],"a":0,"why":"The Ohio River carries coal barges every day."},{"t":"mc","q":"Why is natural gas moved in pipes?","c":["It is a gas, so pipes are the easy way to carry it","It is too heavy for trucks","It is magnetic"],"a":0,"why":"To cross an ocean it is chilled into a liquid first."},{"t":"mc","q":"An electric car charged in Ohio today still uses some fossil fuel. Why?","c":["More than half of Ohio's electricity comes from burning natural gas and coal","The battery is made of coal","The tires burn gas"],"a":0,"why":"How clean an electric car is depends on how its electricity is made."}]],"zone":"fossil"},{"id":"fossilfair","name":"Good At, Costs","blurb":"What fossil fuels do well and what they cost.","badge":"Fair Judge: Fuels","intro":["No energy source is perfect and none is the bad guy. Sort each fact about fossil fuels.","More facts, sorted the same way.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"They work day and night, in any weather.","c":["Something it does well","Something it costs"],"a":0,"why":"A plant can burn fuel whenever power is needed."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A small amount holds a lot of energy.","c":["Something it does well","Something it costs"],"a":0,"why":"One tank of gasoline moves a car hundreds of miles."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Burning them puts carbon dioxide into the air.","c":["Something it does well","Something it costs"],"a":1,"why":"The extra carbon dioxide warms the planet."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Once they are burned, they are gone.","c":["Something it does well","Something it costs"],"a":1,"why":"New ones take millions of years to form."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"They are easy to store until needed.","c":["Something it does well","Something it costs"],"a":0,"why":"Coal sits in a pile. Oil and gas sit in tanks."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Burning them can make the air dirty.","c":["Something it does well","Something it costs"],"a":1,"why":"Filters and cleaner engines help a lot, but not all the way."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Power plants, pipes and gas stations for them are already built.","c":["Something it does well","Something it costs"],"a":0,"why":"That is one reason they are still used so much."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A gas plant can speed up fast when the wind drops or the Sun sets.","c":["Something it does well","Something it costs"],"a":0,"why":"That helps keep the grid in balance."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Mining and drilling disturb land and water.","c":["Something it does well","Something it costs"],"a":1,"why":"Mines and wells have to be cleaned up afterward."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Oil can spill when it is moved.","c":["Something it does well","Something it costs"],"a":1,"why":"Spills harm rivers, seas and wildlife."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"They are light enough to carry on long flights and voyages.","c":["Something it does well","Something it costs"],"a":0,"why":"Batteries are still too heavy for long flights."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Burning coal puts tiny particles in the air that are bad for lungs.","c":["Something it does well","Something it costs"],"a":1,"why":"Modern plants catch most of them. Older ones caught far fewer."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"They can do almost every energy job: cars, planes, heat and electricity.","c":["Something it does well","Something it costs"],"a":0,"why":"They still supply about four fifths of the energy the world uses."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A coal plant turns only about a third of its fuel into electricity.","c":["Something it does well","Something it costs"],"a":1,"why":"The rest leaves as heat."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The price can jump when supplies are cut off far away.","c":["Something it does well","Something it costs"],"a":1,"why":"Fuel is traded all over the world."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Of the three, gas makes the least carbon dioxide for the same electricity.","c":["Something it does well","Something it costs"],"a":0,"why":"Switching from coal to gas lowered power plant carbon dioxide in the United States."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Natural gas that leaks before it is burned warms the planet strongly.","c":["Something it does well","Something it costs"],"a":1,"why":"Methane traps much more heat than the same amount of carbon dioxide."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"They made steel, fertilizer and fast travel cheap enough for most people.","c":["Something it does well","Something it costs"],"a":0,"why":"Much of modern life was built with them."}]],"zone":"fossil"},{"id":"fossilquiz","name":"Quick Quiz","blurb":"Five questions on ancient sunlight.","badge":"Boiler Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"Coal is made from what?","c":["Ancient plants","Melted sand","Sea water"],"a":0,"why":"Pressed for millions of years."},{"t":"mc","q":"Where did the energy in oil first come from?","c":["The Sun","A volcano","A battery"],"a":0,"why":"Sea life caught sunlight long ago."},{"t":"mc","q":"In a steam power plant, what spins the turbine?","c":["Steam","Smoke","Coal dust"],"a":0,"why":"Boiling water makes the steam."},{"t":"mc","q":"What gas does burning put into the air?","c":["Carbon dioxide","Neon","Helium"],"a":0,"why":"It also makes water vapor."},{"t":"mc","q":"Can fossil fuels make power at night?","c":["Yes, any time","No","Only in summer"],"a":0,"why":"That is one thing they do well."}],[{"t":"mc","q":"Why are fossil fuels called nonrenewable?","c":["They take millions of years to form","They are too heavy","They are hard to find"],"a":0,"why":"We use them far faster than they form."},{"t":"mc","q":"What is natural gas mostly?","c":["Methane","Air","Steam"],"a":0,"why":"Methane."},{"t":"mc","q":"What is added to natural gas?","c":["A smell, so leaks are noticed","Color","Sugar"],"a":0,"why":"It smells like rotten eggs."},{"t":"mc","q":"Which makes less carbon dioxide for the same electricity?","c":["Natural gas","Coal","They are equal"],"a":0,"why":"Less than half as much."},{"t":"mc","q":"Most oil formed from what?","c":["Tiny sea life","Dinosaurs","Trees"],"a":0,"why":"Buried under ancient seas."}],[{"t":"mc","q":"About how much of the world's energy comes from fossil fuels?","c":["About four fifths","About one fifth","About half"],"a":0,"why":"Still about four fifths."},{"t":"mc","q":"A coal plant turns about how much of its fuel energy into electricity?","c":["About a third","About nine tenths","About a twentieth"],"a":0,"why":"The rest becomes heat."},{"t":"mc","q":"Why does a modern gas plant waste less?","c":["It uses the heat twice, with two turbines","It burns colder","It has no generator"],"a":0,"why":"Hot gases first, then steam."},{"t":"mc","q":"About when did Ohio's coal form?","c":["About 300 million years ago","About 10,000 years ago","About 1 million years ago"],"a":0,"why":"Before the dinosaurs."},{"t":"mc","q":"Which fuel makes the most electricity in Ohio today?","c":["Natural gas","Coal","Oil"],"a":0,"why":"More than half."}]],"zone":"fossil"}];
const ATOM=[{"id":"reactor","name":"Chain Reaction Lab","blurb":"Slide the control rods and keep the reaction steady.","badge":"Rod Operator","custom":"reactor","intro":["Inside a reactor, tiny bits called neutrons split atoms, and each split gives off heat. Control rods soak up neutrons. Follow the job card.","Fading, steady or growing? Hold the heat in the green band.","Hold it steady, then work out the numbers."],"zone":"atom"},{"id":"atomchain","name":"Atom to Outlet","blurb":"Put the links in order, from an atom to a lamp.","badge":"Atom Tracer","intro":["A nuclear plant is a steam plant with a different way of making heat. Tap the links in order.","Inside the reactor, step by step.","The life of nuclear fuel."],"levels":[[{"t":"order","q":"From an atom to a lamp","links":[["Atoms split","core"],["The splits make heat","ember"],["Water boils into steam","ember"],["Steam spins a turbine","zip"],["A generator makes electricity","spark"]],"why":"Only the first step is different from a coal plant."},{"t":"order","q":"Turning it up","links":[["Workers called operators slide the control rods out a little","core"],["More atoms split","core"],["The water gets hotter","ember"],["More steam flows","zip"]],"why":"The rods are the plant's dimmer switch."},{"t":"order","q":"Cooling the steam","links":[["Steam leaves the turbine","zip"],["Cool lake water in pipes turns it back into water","ember"],["That water goes back to be boiled again","zip"],["The warmed lake water cools off in the tower, making a white cloud","ember"]],"why":"The cloud above a cooling tower is water, not smoke."}],[{"t":"order","q":"One split, step by step","links":[["A neutron hits a uranium atom","core"],["The atom wobbles and splits in two","core"],["Heat is given off and two or three new neutrons fly out","ember"],["One of them hits another atom","core"]],"why":"When each split causes exactly one more, the reaction is steady."},{"t":"order","q":"Shutting down","links":[["Operators push the control rods all the way in","core"],["The rods soak up the neutrons","core"],["The chain reaction stops","core"],["Pumps keep cooling the fuel, which stays warm for a long time","ember"]],"why":"A reactor is cooled even after it is switched off."},{"t":"order","q":"Making fuel","links":[["Uranium ore is mined","stash"],["The uranium is cleaned and concentrated","stash"],["It is pressed into small pellets","stash"],["Pellets are stacked in long metal rods","stash"],["Bundles of rods go into the reactor","core"]],"why":"A pellet is about the size of a pencil eraser."}],[{"t":"order","q":"The life of a fuel rod","links":[["Fresh fuel goes into the reactor","core"],["It makes heat for about four to six years","ember"],["Used fuel cools in a deep pool of water for several years","ember"],["It is sealed in thick steel and concrete casks","stash"],["The casks are stored and guarded","stash"]],"why":"Used fuel stays radioactive for thousands of years, so it has to be kept safely."},{"t":"order","q":"Who found fission","links":[["1938: Otto Hahn and Fritz Strassmann find barium after hitting uranium with neutrons","core"],["Lise Meitner and Otto Frisch work out that the atom had split","core"],["1942: Enrico Fermi's team runs the first reactor, in Chicago","core"],["1951: a reactor in Idaho lights four light bulbs","glow"]],"why":"From the discovery to the first electricity took thirteen years."},{"t":"order","q":"Mass into energy","links":[["A uranium atom splits","core"],["The pieces weigh a tiny bit less than the atom did","core"],["The missing mass has become energy","ember"],["The energy shows up as fast-moving pieces, which is heat","ember"]],"why":"This is what Einstein's famous equation describes."}]],"zone":"atom"},{"id":"atomfacts","name":"Atom Facts","blurb":"What happens inside an atom, and inside a reactor.","badge":"Atom Scholar","intro":["Everything is made of atoms. A few kinds can be split to give off energy.","Splitting, joining, and what the rods do.","Numbers for atom power."],"levels":[[{"t":"mc","q":"What is everything made of?","c":["Atoms","Tiny magnets","Dust only"],"a":0,"why":"Atoms are far too small to see."},{"t":"mc","q":"What happens in a nuclear power plant?","c":["Atoms are split, and that gives off heat","Coal is burned","Wind is caught"],"a":0,"why":"Splitting an atom is called fission."},{"t":"mc","q":"What does the heat do?","c":["Boils water to make steam","Lights the bulbs directly","Makes wind"],"a":0,"why":"Steam spins the turbine, as in other power plants."},{"t":"mc","q":"Does a nuclear plant burn anything?","c":["No","Yes, coal","Yes, gas"],"a":0,"why":"Nothing burns, so no carbon dioxide comes out while it runs."},{"t":"mc","q":"What is the white cloud above a cooling tower?","c":["Water vapor","Smoke","Dust"],"a":0,"why":"It is a cloud, made the same way clouds in the sky are."},{"t":"mc","q":"Did the energy in uranium come from the Sun?","c":["No. It was in the atoms before the Sun formed","Yes, from sunlight on rocks","Yes, from ancient plants"],"a":0,"why":"Nuclear is one of the few sources that did not start as sunlight."}],[{"t":"mc","q":"What metal is the fuel in most nuclear plants?","c":["Uranium","Iron","Gold"],"a":0,"why":"Uranium is dug from the ground as ore."},{"t":"mc","q":"What splits a uranium atom?","c":["A neutron hitting it","A spark","A hammer"],"a":0,"why":"A neutron is one of the tiny bits inside an atom's center."},{"t":"mc","q":"What do control rods do?","c":["Soak up neutrons to slow the reaction","Stir the water","Hold up the roof"],"a":0,"why":"Slide them in and fewer atoms split."},{"t":"mc","q":"The Sun also runs on energy from atoms. How is it different?","c":["The Sun joins small atoms together. A reactor splits big ones","It is the same","The Sun burns coal"],"a":0,"why":"Joining is called fusion. Splitting is called fission."},{"t":"mc","q":"How many nuclear power plants does Ohio have?","c":["Two, both on Lake Erie","None","Twenty"],"a":0,"why":"Davis-Besse and Perry."},{"t":"mc","q":"A banana is very slightly radioactive. Why?","c":["It holds potassium, and a tiny share of all potassium is radioactive","It grew near a power plant","It is yellow"],"a":0,"why":"So are you. Tiny amounts are a normal part of nature."}],[{"t":"mc","q":"One uranium fuel pellet is the size of a pencil eraser. It gives about as much energy as how much coal?","c":["About a ton","About a cupful","About a whole train"],"a":0,"why":"That is why a reactor needs new fuel only every year and a half or two years."},{"t":"mc","q":"About how much of the electricity in the United States comes from nuclear plants?","c":["About one sixth","About one hundredth","About three quarters"],"a":0,"why":"94 reactors make it."},{"t":"mc","q":"Which country gets most of its electricity from nuclear plants?","c":["France","Australia","Iceland"],"a":0,"why":"About two thirds of France's electricity."},{"t":"mc","q":"Natural uranium is mostly a kind that does not split easily. About how much is the kind that does, called uranium-235?","c":["Less than 1 part in 100","About half","All of it"],"a":0,"why":"Fuel is enriched until about 3 to 5 parts in 100 are uranium-235."},{"t":"mc","q":"About how much of the year does a typical United States reactor run at full power?","c":["About nine tenths","About half","About a quarter"],"a":0,"why":"It stops mostly for refueling."},{"t":"mc","q":"Who first worked out that the uranium atom had split in two?","c":["Lise Meitner and Otto Frisch","Thomas Edison","James Joule"],"a":0,"why":"In 1938, explaining an experiment by Otto Hahn and Fritz Strassmann."}]],"zone":"atom"},{"id":"atomparts","name":"Parts of the Plant","blurb":"What each part of a nuclear plant is for.","badge":"Plant Mapper","intro":["A nuclear plant has a few big parts. What is each one for?","More parts, and what they do.","How the parts work together."],"levels":[[{"t":"mc","q":"Where do the atoms split?","c":["In the reactor","In the cooling tower","In the wires"],"a":0,"why":"The reactor is a thick steel tank."},{"t":"mc","q":"What spins to make electricity?","c":["The turbine and generator","The fuel","The cooling tower"],"a":0,"why":"Steam pushes the turbine blades."},{"t":"mc","q":"What is the cooling tower for?","c":["Cooling the water so it can be used again","Burning fuel","Storing electricity"],"a":0,"why":"It lets off water vapor."},{"t":"mc","q":"What carries the electricity away?","c":["Power lines","Steam pipes","Trucks"],"a":0,"why":"The same lines any power plant uses."},{"t":"mc","q":"What is in the fuel rods?","c":["Small pellets of uranium","Coal","Water"],"a":0,"why":"Stacked like coins in a long tube."}],[{"t":"mc","q":"What is the thick concrete building around the reactor for?","c":["Keeping radioactive material sealed inside","Keeping rain out","Holding the turbine"],"a":0,"why":"It is called the containment building. Its walls are several feet thick."},{"t":"mc","q":"What moves in and out to change how many atoms split?","c":["Control rods","Fuel pellets","The turbine"],"a":0,"why":"They soak up neutrons."},{"t":"mc","q":"What does the water around the fuel do?","c":["Carries the heat away and helps the reaction work","Puts out a fire","Nothing"],"a":0,"why":"In most reactors water also slows the neutrons, which helps them split atoms."},{"t":"mc","q":"Where does used fuel go first?","c":["Into a deep pool of water to cool","Into the river","Into the cooling tower"],"a":0,"why":"The water cools it and blocks its radiation."},{"t":"mc","q":"Who watches the reactor?","c":["Trained operators in a control room, day and night","Nobody","Robots only"],"a":0,"why":"Operators train for years and practice on simulators."}],[{"t":"mc","q":"In many plants, the water that touches the fuel never reaches the turbine. Why two separate loops?","c":["To keep anything radioactive away from the turbine side","To save paint","To make more noise"],"a":0,"why":"The first loop heats the second through metal tubes."},{"t":"mc","q":"If a reactor gets hotter than it should, what do the safety systems do on their own?","c":["Drop the control rods in to stop the reaction","Open the doors","Turn up the turbine"],"a":0,"why":"It takes only a few seconds."},{"t":"mc","q":"After the chain reaction stops, why must the fuel still be cooled?","c":["The split pieces keep giving off heat for a long time","The steam is cold","The rods are lonely"],"a":0,"why":"Backup pumps and generators are there for that job."},{"t":"mc","q":"What are dry casks?","c":["Thick steel and concrete containers for used fuel that has cooled","Barrels of spare water","Empty fuel rods"],"a":0,"why":"They sit on a concrete pad and are guarded and checked."},{"t":"mc","q":"From the turbine onward, how does a nuclear plant differ from a coal plant?","c":["Hardly at all","It has no generator","It uses wind"],"a":0,"why":"Turbine, generator and power lines are the same idea."}]],"zone":"atom"},{"id":"atomfair","name":"Good At, Costs","blurb":"What nuclear power does well and what it costs.","badge":"Fair Judge: Atoms","intro":["No energy source is perfect and none is the bad guy. Sort each fact about nuclear power.","More facts, sorted the same way.","The grown-up facts. Sort them the same way."],"levels":[[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It runs day and night, in any weather.","c":["Something it does well","Something it costs"],"a":0,"why":"A reactor runs for many months without stopping."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes no carbon dioxide while it runs.","c":["Something it does well","Something it costs"],"a":0,"why":"Nothing is burned."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A plant costs a great deal of money to build.","c":["Something it does well","Something it costs"],"a":1,"why":"It takes thousands of workers and many years."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The used fuel has to be stored very carefully.","c":["Something it does well","Something it costs"],"a":1,"why":"It stays radioactive, which means it gives off invisible rays, for a very long time. Strong radiation can harm living things, so the fuel is kept behind thick water, steel and concrete."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A tiny amount of fuel makes a huge amount of energy.","c":["Something it does well","Something it costs"],"a":0,"why":"One pellet matches about a ton of coal."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It needs many safety systems and trained people.","c":["Something it does well","Something it costs"],"a":1,"why":"That care is part of why it costs so much."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It takes up little land for the power it makes.","c":["Something it does well","Something it costs"],"a":0,"why":"One reactor can power several hundred thousand homes from a small site."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A new plant can take ten years or more to build.","c":["Something it does well","Something it costs"],"a":1,"why":"Wind and solar farms are built much faster."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Uranium has to be mined.","c":["Something it does well","Something it costs"],"a":1,"why":"Mining disturbs land, like any mining."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Fuel is loaded only every year and a half or two years.","c":["Something it does well","Something it costs"],"a":0,"why":"A plant does not need a train of fuel every day."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It is slow to turn up and down.","c":["Something it does well","Something it costs"],"a":1,"why":"Most reactors run best at one steady level."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The amount of used fuel is small.","c":["Something it does well","Something it costs"],"a":0,"why":"If all of one person's electricity for a whole lifetime came from nuclear, the used fuel would about fill a soda can. Its thick storage cask is far bigger."}],[{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"It makes about a sixth of the electricity in the United States, more than any other single source that makes no carbon dioxide.","c":["Something it does well","Something it costs"],"a":0,"why":"It has been a steady share for decades."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"The United States has no permanent place to put used fuel yet.","c":["Something it does well","Something it costs"],"a":1,"why":"For now it stays in pools and casks at the plants."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"United States reactors run at full power about nine tenths of the year.","c":["Something it does well","Something it costs"],"a":0,"why":"No other kind of plant runs as steadily."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Electricity from a newly built plant costs more than electricity from new wind or solar farms.","c":["Something it does well","Something it costs"],"a":1,"why":"The plant is the big cost. The fuel is a small one."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"Reactors need a lot of water for cooling.","c":["Something it does well","Something it costs"],"a":1,"why":"Like every steam plant. That is why they sit on lakes, rivers and coasts."},{"t":"mc","fixed":1,"pre":"Every energy source does some things well and has some costs. Which is this?","q":"A plant can run for 60 years or longer.","c":["Something it does well","Something it costs"],"a":0,"why":"Many have had their licenses extended."}]],"zone":"atom"},{"id":"atomquiz","name":"Quick Quiz","blurb":"Five questions on atom power.","badge":"Atom Whiz","intro":["Five quick ones. Take your time.","Five quick ones. Take your time.","Five hard ones. Take your time."],"levels":[[{"t":"mc","q":"What gives off the heat in a nuclear plant?","c":["Splitting atoms","Burning coal","Rubbing wires"],"a":0,"why":"It is called fission."},{"t":"mc","q":"What does the heat boil?","c":["Water","Oil","Sand"],"a":0,"why":"The steam spins a turbine."},{"t":"mc","q":"What comes out of a cooling tower?","c":["Water vapor","Smoke","Sparks"],"a":0,"why":"A white cloud."},{"t":"mc","q":"Does a nuclear plant work at night?","c":["Yes","No","Only when it is windy"],"a":0,"why":"Day and night."},{"t":"mc","q":"Did uranium's energy start as sunlight?","c":["No","Yes","Only in summer"],"a":0,"why":"It is one of the few that did not."}],[{"t":"mc","q":"What do control rods soak up?","c":["Neutrons","Water","Electricity"],"a":0,"why":"Fewer neutrons, fewer splits."},{"t":"mc","q":"Splitting atoms is called what?","c":["Fission","Fusion","Friction"],"a":0,"why":"Fusion is joining."},{"t":"mc","q":"What is the fuel?","c":["Uranium","Coal","Iron"],"a":0,"why":"Pressed into pellets."},{"t":"mc","q":"Where does used fuel go first?","c":["A deep pool of water","A river","A field"],"a":0,"why":"To cool."},{"t":"mc","q":"How many nuclear plants are in Ohio?","c":["Two","Zero","Ten"],"a":0,"why":"Davis-Besse and Perry."}],[{"t":"mc","q":"For a steady reaction, each split must cause how many more?","c":["Exactly one","Two","Zero"],"a":0,"why":"More than one grows. Fewer than one fades."},{"t":"mc","q":"One fuel pellet matches about how much coal?","c":["A ton","A pound","A shovel"],"a":0,"why":"About a ton."},{"t":"mc","q":"About what share of United States electricity is nuclear?","c":["About a sixth","A half","A fiftieth"],"a":0,"why":"About a sixth."},{"t":"mc","q":"The kind of uranium that splits easily is called what?","c":["Uranium-235","Uranium-12","Carbon-14"],"a":0,"why":"Less than 1 part in 100 of natural uranium."},{"t":"mc","q":"What is one big cost of nuclear power?","c":["Plants are very expensive and slow to build","It works only in daylight","It needs coal"],"a":0,"why":"The other is storing used fuel for a very long time."}]],"zone":"atom"}];
const BIGM={"name":"Energy Chain Hunt","badge":"Chain Hunter","time":"About 20 minutes","where":"Indoors","supplies":["Paper","Pencil or markers"],"steps":["Walk around your home and pick things that use energy.","Just look. Do not touch outlets, plugs, the stove or anything hot. Ask a grown-up if you want a closer look.","For each one, ask: where did its energy come from? And before that? And before that?","Draw the chain as boxes with arrows, back to the very start.","Ask a grown-up to help you take a photo of your best chain to stamp your mission."],"lv":["Pick 3 things. Draw 3 links for each.","Pick 5 things. Follow each one all the way back to the start.","Pick 5 things and follow each one back. Then look for a chain that does not start with sunlight. Hint: some of Ohio's electricity comes from nuclear plants."]};
const ELECM={"name":"Lemon Battery","badge":"Lemon Power","time":"About 30 minutes","where":"Indoors, at a table, with a grown-up","supplies":["4 lemons","4 zinc-coated (galvanized) nails","4 pennies or short pieces of copper wire","5 clip leads or pieces of wire","1 small red LED"],"steps":["Roll each lemon on the table to loosen the juice inside.","A grown-up cuts a small slit in each lemon. Push a bright, clean penny halfway into the slit and a nail into the other side. The two metals must not touch inside the lemon.","Join the lemons in a row: wire from the nail of one lemon to the penny of the next.","You now have one free penny and one free nail. Connect the LED's longer leg to the free penny and its shorter leg to the free nail.","Dim the room and look closely. The glow is faint. If it stays dark, check that every clip touches metal, swap the LED's legs, and squeeze the lemons gently.","Ask a grown-up to help you take a photo to stamp your mission.","Throw the lemons away. They are not for eating. Wash your hands, keep juice away from your eyes, and put the nails, pennies and LED where little children cannot reach them."],"lv":["Build it and find the glow.","Test it with 2 lemons, then 3, then 4. How many does the LED need?","Predict first: will potatoes work in place of the lemons? Will the LED be brighter or dimmer? Then swap all four and see."]};
const SUNM={"name":"Pizza-Box Solar Oven","badge":"Sun Chef","time":"About 20 minutes to build, 30 to 60 minutes to cook","where":"Outdoors on a warm, calm, sunny day, with a grown-up","supplies":["A clean pizza box","Scissors or a box cutter, for the grown-up only","Aluminum foil","Plastic wrap","Black paper","Tape","A ruler or stick","A graham cracker, a piece of chocolate and a marshmallow"],"steps":["A grown-up cuts a flap in the lid: three sides of a square, about one inch in from the edges. Fold the flap up along the uncut side.","Cover the inside of the flap with foil, shiny side out. Smooth it flat.","Tape plastic wrap across the hole the flap left, so the box is sealed. Two layers work better than one.","Line the bottom of the box with black paper.","First the eye rule: never look at the Sun or at its bright reflection in the foil. Then put the s'more on a small plate inside, close the lid, and prop the flap open with the ruler so it bounces sunlight down into the box.","Set the oven in full Sun, best between 11 and 3. Wait, and check on it through the plastic.","Open the lid carefully. The inside and the food are hot.","The s'more is for big kids. Marshmallows are a choking risk for children under 4, so keep it and the plastic wrap away from little brothers and sisters.","Ask a grown-up to help you take a photo to stamp your mission."],"lv":["Time how long the chocolate takes to melt.","Build it, then test one change: flap up, or flap folded away. Which melts the chocolate faster?","Put an oven thermometer inside and write down the temperature every 10 minutes. Chart it in Data Lab. In the cooler months, prop the whole box so the window faces the low Sun, and expect it to take longer."]};
const WINDM={"name":"Pinwheel Winch","badge":"Wind Lifter","time":"About 30 minutes","where":"Indoors, with a grown-up","supplies":["A square of paper about 6 inches wide","A wooden skewer","A drinking straw","Tape","Thread about 2 feet long","Paper clips","Scissors"],"steps":["Cut the paper square from each corner toward the middle. Stop about an inch from the center.","Bend every other point into the center and tape them down. That is your pinwheel.","A grown-up pushes the pointed skewer through the center of the pinwheel, then snips off the sharp point and covers the cut end with tape. Tape the pinwheel so it grips the skewer and cannot slip.","Slide the skewer through the straw. Tape the straw across a corner of the table, so both ends of the skewer stick out past the table.","Wrap a small ring of tape around the skewer at each end of the straw. The skewer should not slide, but it should still spin.","Tie the thread to the bare end of the skewer and tape the knot. Let it hang down beside the table, and hook a paper clip on the loose end.","Blow on the pinwheel. The thread winds up and lifts the clip. Add clips until it cannot lift any more.","Keep the paper clips, thread and skewer away from little brothers and sisters, and put them away when you finish.","Ask a grown-up to help you take a photo to stamp your mission."],"lv":["How many paper clips can your pinwheel lift?","Make a second pinwheel from an 8-inch square. Does the bigger one lift more?","A small paper clip weighs about 1 gram. Weigh 10 on a kitchen scale if you have one. Time how long your pinwheel takes to lift 10 clips half a meter. Lifting them takes about 0.05 joules. Divide by the seconds to get watts."]};
const WATERM={"name":"Spoon Water Wheel","badge":"Wheel Wright","time":"About 30 minutes","where":"At the kitchen sink, with a grown-up","supplies":["A small foam ball, or a cork","6 plastic spoons","A wooden skewer","Scissors, for the grown-up","2 paper cups","A marker","A timer","A towel"],"steps":["A grown-up cuts the spoon handles short, to about an inch. Hard plastic can snap, so cut inside a paper bag or under the towel, and throw the cut-off pieces away right then.","Push a spoon handle into the foam ball, then five more, evenly around its middle. All the bowls face the same way around, like paddles. With a cork, a grown-up makes the slits first, with the cork lying on a cutting board.","A grown-up lays the ball on the table and pushes the skewer down through its middle, never toward a hand, then snips off the sharp point.","A grown-up cuts a small V in the rim of each paper cup. Rest the ends of the skewer in the two notches so the wheel can spin, or hold the ends loosely in your fingers.","Color one spoon with the marker so you can count turns.","Run a thin stream of cold water onto the spoons. The wheel turns.","Wipe up spills so nobody slips. Put the wheel and every cut piece up high or in the bin, away from little brothers and sisters.","Ask a grown-up to help you take a photo to stamp your mission."],"lv":["Count how many times the wheel turns in 10 seconds.","Hold the wheel just under the tap, then as low in the sink as you can. Count the turns in 10 seconds each time. Does the longer fall spin it faster?","Test two things, one at a time: the height of the fall, and how far the tap is open. Which one changes the speed more? Chart your counts in Data Lab."]};
const GEOM={"name":"Ground Thermometer","badge":"Ground Reader","time":"10 minutes, twice in one day","where":"Outdoors in the yard, with a grown-up","supplies":["A kitchen or soil thermometer with a metal probe","A hand trowel","Paper and pencil"],"steps":["Ask a grown-up where it is OK to dig. Use a garden bed that has been dug before. Sprinkler, yard-light and dog-fence wires can be only a few inches down, so stop if you hit anything hard.","The probe is pointed. Carry it tip down and keep it away from little brothers and sisters.","On a cold morning, hold the thermometer in the shade for two minutes. Write down the air temperature.","Dig a narrow hole about as deep as your hand is long. Push the probe into the soil at the bottom, wait two minutes and write down the number.","Fill the hole back in.","Do it again in the afternoon, in the same spot.","Wash your hands, and wash the probe with soap before it goes back in the kitchen.","Ask a grown-up to help you take a photo of your numbers to stamp your mission."],"lv":["Which was warmer on the cold morning: the air or the soil?","Compare morning and afternoon. Which changed more, the air or the soil?","Measure every day for a week and chart both lines in Data Lab. The soil line should be the flatter one. On a sunny summer afternoon the top of the soil can be hotter than the air. Deeper down it is steadier still, and that is where a heat pump puts its pipes."]};
const CONTROLM={"name":"Watt Hunt","badge":"Watt Hunter","time":"About 20 minutes","where":"Indoors, with a grown-up","supplies":["Paper and pencil","A flashlight for reading small labels","A calculator"],"steps":["With a grown-up, pick 8 things at home that use electricity. Good ones: a toaster, a lamp, a phone charger, a hair dryer, a fan, a night light, a TV, a microwave.","Ask your grown-up to unplug each one. Hold the plug, not the cord, with dry hands. Skip the toaster and hair dryer if they were used in the last half hour.","Do not move the TV or the microwave. A grown-up can read the TV label on the back. The microwave label is inside the door.","Find the label and look for a number followed by W, for watts. On a lamp, read the bulb. On a phone charger, use the OUTPUT line. If a label shows two watt numbers, use the bigger one.","No W on the label? Find V and A and multiply them on the calculator.","Write each thing and its watts in a list, then put the list in order from fewest watts to most.","Plug things back in or put them away when you finish, so no cords or open outlets are left for little brothers or sisters.","Ask a grown-up to help you take a photo of your list to stamp your mission."],"lv":["Which thing uses the most watts? Which uses the fewest?","Circle the things that make heat on purpose. Where do they sit in your list?","Add up all 8 on the calculator. Brightwater needs 18 megawatts at its peak, which is 18,000,000 watts. How many times bigger is that than your total? Chart your list in Data Lab."]};
const FOODM={"name":"Stair Power","badge":"Stair Climber","time":"About 20 minutes","where":"On a staircase at home, with a grown-up","supplies":["A staircase with a handrail","A ruler or tape measure","A timer","A calculator","Paper and pencil"],"steps":["Measure how tall one step is. Count the steps and multiply to get the height of the whole flight. Change it to meters: inches times 0.0254.","Clear the stairs. Shoes on, or bare feet. No socks. Little brothers and sisters stay off the stairs while you test.","Walk up at your normal speed, holding the rail, while a grown-up times you. Do not run. Walk back down slowly, holding the rail. Only the climb up is timed.","Do it twice more and write down all three times.","Walk up once more at a quick walk, one step at a time, still holding the rail, and time that too. This is not a race. No skipping steps.","Ask a grown-up to help you take a photo of your numbers to stamp your mission."],"lv":["Which took fewer seconds, the normal walk or the faster one? In which did your legs work harder?","Find your middle time of the three normal walks. Why is it a good idea to measure three times?","Work out your power. Use 28 kilograms. The lab uses that same round number for every kid. Watts = 28 × 9.8 × meters ÷ seconds. Compare it with the 40 watts of steady pedaling. A short climb comes out higher, because you only hold it for a few seconds."]};
const FOSSILM={"name":"Fuel Detective","badge":"House Inspector","time":"About 20 minutes","where":"At home, with a grown-up. Look, do not touch","supplies":["Paper and pencil","A grown-up to walk with you","A flashlight, if the basement is dim"],"steps":["Make three columns on your paper: burns fuel here, runs on electricity, runs on muscle.","Walk through the house with your grown-up. Hold the handrail on the basement stairs. Find the furnace, the water heater, the stove, the clothes dryer and the car. The car stays parked and switched off. Look only. Do not touch pipes, knobs or anything warm.","Ask your grown-up which column each one goes in, and write it down.","Add five more things of your own, like a lamp, a bike or the lawn mower.","Count each column.","Ask a grown-up to help you take a photo of your list to stamp your mission."],"lv":["Which column is longest in your house?","For everything in the electricity column: where is the fuel burned, if any is burned? Hint: think about the power plant.","Pick one thing that burns fuel in your house. What would it take to run it on electricity? What might be good about that, and what might it cost?"]};
const ATOMM={"name":"Domino Chain Reaction","badge":"Chain Builder","time":"About 30 minutes","where":"On a table or a hard floor","supplies":["About 30 dominoes, or small blocks, or paperback books stood on end","A thick book"],"steps":["Keep small pieces up off the floor if a little brother or sister is around.","Line up 15 dominoes in one straight row, about a finger-width apart. Tip the first one. Each domino knocks down exactly one more.","Now build a fan. One domino knocks down two: set the two just behind it, a little to each side. Each of those knocks down two more, and so on, for four rows: 1, 2, 4, 8.","Tip the first domino of the fan and watch how fast the falling spreads.","Build the straight row again, but lay a thick book flat between two dominoes in the middle. Tip the first one.","Ask a grown-up to help you take a photo of your fan to stamp your mission."],"lv":["Which finished faster once it got going, the straight row or the fan?","In the row, each fall caused one more. In the fan, each caused two. Which one is like a reactor running steady? What did the book do, and which part of a reactor does that job?","If the fan kept going, how many dominoes would the tenth row need? Start from 1 and double nine times."]};
